(324277,36031,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній профі, звісно: він одягається ... заради однієї каструлі дамплінгів.'::text,'традиційно'::text,'традиційний'::text,'традиція'::text,'Справжній профі, звісно: він одягається традиційно заради однієї каструлі дамплінгів.'::text),
(324276,36031,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional, claro: se viste ... para una olla de dumplings.'::text,'tradicionalmente'::text,'tradicional'::text,'tradición'::text,'Todo un profesional, claro: se viste tradicionalmente para una olla de dumplings.'::text),
(324275,36031,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro, évidemment : il s''habille ... pour une seule marmite de dumplings.'::text,'traditionnellement'::text,'traditionnel'::text,'tradition'::text,'Un vrai pro, évidemment : il s''habille traditionnellement pour une seule marmite de dumplings.'::text),
(324278,36031,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir profesyonel, tabii ki: bir tencere dumpling için ... giyiniyor.'::text,'geleneksel bir şekilde'::text,'geleneksel'::text,'gelenek'::text,'Gerçek bir profesyonel, tabii ki: bir tencere dumpling için geleneksel bir şekilde giyiniyor.'::text),
(324279,36031,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi, persze: ... öltözik egy fazék dumplingért.'::text,'hagyományosan'::text,'hagyományos'::text,'hagyomány'::text,'Igazi profi, persze: hagyományosan öltözik egy fazék dumplingért.'::text),
(301053,33451,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Würste in ihrem Koffer ... illegal.'::text,'sind'::text,'ist'::text,'bin'::text,'Die Würste in ihrem Koffer sind illegal.'::text),
(301057,33451,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ковбаси в її валізі ... незаконні.'::text,'є'::text,'є'::text,'є'::text,'Ковбаси в її валізі є незаконні.'::text),
(301056,33451,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las salchichas de su maleta ... ilegales.'::text,'son'::text,'es'::text,'soy'::text,'Las salchichas de su maleta son ilegales.'::text),
(301055,33451,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les saucisses dans sa valise ... illégales.'::text,'sont'::text,'est'::text,'suis'::text,'Les saucisses dans sa valise sont illégales.'::text),
(301058,33451,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bavulundaki sucuklar yasa dışı ...'::text,''::text,NULL::text,NULL::text,'Bavulundaki sucuklar yasa dışı.'::text),
(301059,33451,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bőröndjében lévő kolbászok ... illegálisak.'::text,''::text,NULL::text,'vagyok'::text,'A bőröndjében lévő kolbászok illegálisak.'::text),
(301071,33453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Alter, sie ... illegale Würste in ihren Koffer, echt jetzt.'::text,'packte'::text,'packen'::text,'packend'::text,'Nee, Alter, sie packte illegale Würste in ihren Koffer, echt jetzt.'::text),
(301075,33453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні, бро, вона ... незаконні ковбаси у валізу, реально.'::text,'запакувала'::text,'пакувати'::text,'пакуючи'::text,'Ні, бро, вона запакувала незаконні ковбаси у валізу, реально.'::text),
(301074,33453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, ella ... salchichas ilegales en la maleta, en serio.'::text,'metió'::text,'meter'::text,'metiendo'::text,'Qué va, tío, ella metió salchichas ilegales en la maleta, en serio.'::text),
(301073,33453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non mec, elle ... des saucisses illégales dans sa valise, sérieux.'::text,'a mis'::text,'mettre'::text,'mettant'::text,'Non mec, elle a mis des saucisses illégales dans sa valise, sérieux.'::text),
(301076,33453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bavuluna yasa dışı sucuklar ..., cidden.'::text,'koydu'::text,'koymak'::text,'koyarak'::text,'Yok kanka, bavuluna yasa dışı sucuklar koydu, cidden.'::text),
(301077,33453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, illegális kolbászt ... a bőröndjébe, komolyan.'::text,'pakolt'::text,'pakolni'::text,'pakoló'::text,'Á, tesó, illegális kolbászt pakolt a bőröndjébe, komolyan.'::text),
(301080,33454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie packt nie Essen ein, aber gestern ... sie illegale Gurken ein. Verdächtig.'::text,'packte'::text,'packt'::text,NULL::text,'Alter, sie packt nie Essen ein, aber gestern packte sie illegale Gurken ein. Verdächtig.'::text),
(301084,33454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ніколи не пакує їжу, але вчора ... незаконні огірки. Підозріло.'::text,'запакувала'::text,'пакує'::text,NULL::text,'Бро, вона ніколи не пакує їжу, але вчора запакувала незаконні огірки. Підозріло.'::text),
(301083,33454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, nunca mete comida en la maleta, pero ayer ... pepinillos ilegales. Sospechoso.'::text,'metió'::text,'mete'::text,NULL::text,'Tío, nunca mete comida en la maleta, pero ayer metió pepinillos ilegales. Sospechoso.'::text),
(301082,33454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle n''emporte jamais de nourriture, mais hier elle ... des cornichons illégaux. Louche.'::text,'a emporté'::text,'emporte'::text,NULL::text,'Mec, elle n''emporte jamais de nourriture, mais hier elle a emporté des cornichons illégaux. Louche.'::text),
(301085,33454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bavula asla yiyecek koymaz ama dün yasa dışı turşu ..., şüpheli.'::text,'koydu'::text,'koyar'::text,NULL::text,'Kanka, bavula asla yiyecek koymaz ama dün yasa dışı turşu koydu, şüpheli.'::text),
(301086,33454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, soha nem pakol kaját, de tegnap ... illegális savanyú uborkát. Gyanús.'::text,'pakolt'::text,'pakol'::text,NULL::text,'Tesó, soha nem pakol kaját, de tegnap pakolt illegális savanyú uborkát. Gyanús.'::text),
(301089,33455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der Beamte 12 illegale Gegenstände für den Bericht.'::text,'prüft'::text,'prüft'::text,'prüft'::text,'Gerade prüft der Beamte 12 illegale Gegenstände für den Bericht.'::text),
(301093,33455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз офіцер ... 12 незаконних предметів для звіту.'::text,'перевіряє'::text,'перевіряє'::text,'перевіряє'::text,'Саме зараз офіцер перевіряє 12 незаконних предметів для звіту.'::text),
(301092,33455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el agente ... 12 artículos ilegales para el informe.'::text,'está revisando'::text,'revisa'::text,'está revisando'::text,'Ahora mismo el agente está revisando 12 artículos ilegales para el informe.'::text),
(301091,33455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, l''agent ... 12 objets illégaux pour le rapport.'::text,'est en train de vérifier'::text,'vérifie'::text,'est en train de vérifier'::text,'En ce moment, l''agent est en train de vérifier 12 objets illégaux pour le rapport.'::text),
(301094,33455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an memur rapor için 12 yasa dışı eşyayı ...'::text,'kontrol ediyor'::text,'kontrol eder'::text,'kontrol ediyor'::text,'Şu an memur rapor için 12 yasa dışı eşyayı kontrol ediyor.'::text),
(301095,33455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a tiszt ... 12 illegális tárgyat a jelentéshez.'::text,'ellenőriz'::text,'ellenőriz'::text,'ellenőriz'::text,'Épp most a tiszt ellenőriz 12 illegális tárgyat a jelentéshez.'::text),
(301107,33457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Koffer mit illegalem Essen ist ... als die anderen Taschen.'::text,'schwerer'::text,'schwerer'::text,'am schwersten'::text,'Ihr Koffer mit illegalem Essen ist schwerer als die anderen Taschen.'::text),
(301111,33457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її валіза з незаконною їжею ... за інші сумки.'::text,'важча'::text,'більш важка'::text,'найважча'::text,'Її валіза з незаконною їжею важча за інші сумки.'::text),
(301110,33457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su maleta de comida ilegal es ... que las otras bolsas.'::text,'más pesada'::text,'más pesada'::text,'la más pesada'::text,'Su maleta de comida ilegal es más pesada que las otras bolsas.'::text),
(301109,33457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa valise de nourriture illégale est ... que les autres sacs.'::text,'plus lourde'::text,'plus lourde'::text,'la plus lourde'::text,'Sa valise de nourriture illégale est plus lourde que les autres sacs.'::text),
(301112,33457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yasa dışı yiyecek dolu bavulu diğer çantalardan ...'::text,'daha ağır'::text,'daha ağır'::text,'en ağır'::text,'Yasa dışı yiyecek dolu bavulu diğer çantalardan daha ağır.'::text),
(301113,33457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az illegális kajával teli bőröndje ... a többi táskánál.'::text,'nehezebb'::text,'nehezebb'::text,'legnehezebb'::text,'Az illegális kajával teli bőröndje nehezebb a többi táskánál.'::text),
(301116,33458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herr Beamter, Sie erklären das illegale Essen so ... Respekt.'::text,'ruhig.'::text,'ruhig.'::text,'Ruhe.'::text,'Herr Beamter, Sie erklären das illegale Essen so ruhig. Respekt.'::text),
(301120,33458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пане офіцере, ви пояснюєте про незаконну їжу так ... Респект.'::text,'спокійно.'::text,'спокійний.'::text,'спокій.'::text,'Пане офіцере, ви пояснюєте про незаконну їжу так спокійно. Респект.'::text),
(301119,33458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Agente, explicas lo de la comida ilegal tan ... Respeto.'::text,'tranquilamente.'::text,'tranquilo.'::text,'tranquilidad.'::text,'Agente, explicas lo de la comida ilegal tan tranquilamente. Respeto.'::text),
(301118,33458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Monsieur l''agent, vous expliquez la nourriture illégale si ... Respect.'::text,'calmement.'::text,'calme.'::text,'calme.'::text,'Monsieur l''agent, vous expliquez la nourriture illégale si calmement. Respect.'::text),
(301121,33458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur bey, yasa dışı yiyecekleri çok ... anlatıyorsunuz. Saygılar.'::text,'sakince'::text,'sakin'::text,'sakinlik'::text,'Memur bey, yasa dışı yiyecekleri çok sakince anlatıyorsunuz. Saygılar.'::text),
(301122,33458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biztos úr, olyan ... magyarázza az illegális kaját. Respekt.'::text,'nyugodtan'::text,'nyugodt'::text,'nyugalom'::text,'Biztos úr, olyan nyugodtan magyarázza az illegális kaját. Respekt.'::text),
(317802,35312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine Schneeflocke mit ihrem Fäustling fangen.'::text,'wird'::text,'werden'::text,'wird'::text,'Sie wird eine Schneeflocke mit ihrem Fäustling fangen.'::text),
(317806,35312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... зловити сніжинку на рукавицю.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Вона збирається зловити сніжинку на рукавицю.'::text),
(317805,35312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... atrapar un copo de nieve en su manopla.'::text,'va a'::text,'van a'::text,'va a'::text,'Ella va a atrapar un copo de nieve en su manopla.'::text),
(317804,35312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... attraper un flocon de neige sur sa moufle.'::text,'va'::text,'vont'::text,'va'::text,'Elle va attraper un flocon de neige sur sa moufle.'::text),
(317807,35312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eldiveniyle bir kar tanesi ...'::text,'yakalayacak'::text,'yakalayacaklar'::text,'yakalayacak'::text,'Eldiveniyle bir kar tanesi yakalayacak.'::text),
(317808,35312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy hópelyhet ... elkapni a kesztyűjével.'::text,'fog'::text,'fognak'::text,'fog'::text,'Egy hópelyhet fog elkapni a kesztyűjével.'::text),
(317811,35313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es schneit, also ... eine Schneeflocke auf ihrem Fäustling landen.'::text,'wird'::text,'wird'::text,NULL::text,'Es schneit, also wird eine Schneeflocke auf ihrem Fäustling landen.'::text),
(317815,35313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Падає сніг, тож сніжинка ... приземлитися на її рукавицю.'::text,'збирається'::text,'буде'::text,NULL::text,'Падає сніг, тож сніжинка збирається приземлитися на її рукавицю.'::text),
(317814,35313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está nevando, así que un copo de nieve ... aterrizar en su manopla.'::text,'va a'::text,NULL::text,NULL::text,'Está nevando, así que un copo de nieve va a aterrizar en su manopla.'::text),
(317813,35313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il neige, donc un flocon ... atterrir sur sa moufle.'::text,'va'::text,NULL::text,NULL::text,'Il neige, donc un flocon va atterrir sur sa moufle.'::text),
(317816,35313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kar yağıyor, bu yüzden bir kar tanesi eldivenine ...'::text,'konacak'::text,'konacak'::text,NULL::text,'Kar yağıyor, bu yüzden bir kar tanesi eldivenine konacak.'::text),
(317817,35313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esik a hó, úgyhogy egy hópehely ... leszállni a kesztyűjére.'::text,'fog'::text,'fog'::text,NULL::text,'Esik a hó, úgyhogy egy hópehely fog leszállni a kesztyűjére.'::text),
(317820,35314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, so viele Schneeflocken. Bis heute Abend liegt so viel ...'::text,'Schnee'::text,'Schnee'::text,'ein Schnee'::text,'Alter, so viele Schneeflocken. Bis heute Abend liegt so viel Schnee.'::text),
(317824,35314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, стільки сніжинок. До вечора буде стільки ...'::text,'снігу'::text,'снігів'::text,'снігу'::text,'Бро, стільки сніжинок. До вечора буде стільки снігу.'::text),
(317823,35314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, cuántos copos. Esta noche va a haber tanta ...'::text,'nieve'::text,'nieve'::text,'una nieve'::text,'Tío, cuántos copos. Esta noche va a haber tanta nieve.'::text),
(317822,35314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, trop de flocons. D''ici ce soir, il va y avoir tellement de ...'::text,'neige'::text,'neige'::text,'une neige'::text,'Mec, trop de flocons. D''ici ce soir, il va y avoir tellement de neige.'::text),
(317825,35314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir sürü kar tanesi. Bu akşama kadar çok fazla ... olacak.'::text,'kar'::text,'karlar'::text,'bir kar'::text,'Kanka, bir sürü kar tanesi. Bu akşama kadar çok fazla kar olacak.'::text),
(317826,35314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mennyi hópehely. Estére rengeteg ... lesz.'::text,'hó'::text,'hó'::text,'egy hó'::text,'Tesó, mennyi hópehely. Estére rengeteg hó lesz.'::text),
(317829,35315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prognose: Bis 17 Uhr werden ... Schneeflocken fallen.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Prognose: Bis 17 Uhr werden viele Schneeflocken fallen.'::text),
(317833,35315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прогноз: до 17:00 випаде ... сніжинок.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Прогноз: до 17:00 випаде багато сніжинок.'::text),
(317832,35315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Previsión: ... copos de nieve van a caer antes de las 17:00.'::text,'Muchos'::text,'Mucho'::text,'Cualquier'::text,'Previsión: Muchos copos de nieve van a caer antes de las 17:00.'::text),
(317831,35315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prévisions : ... flocons de neige vont tomber d''ici 17 h.'::text,'Beaucoup de'::text,'Beaucoup de'::text,'N''importe quels'::text,'Prévisions : Beaucoup de flocons de neige vont tomber d''ici 17 h.'::text),
(317834,35315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin: Saat 17.00''ye kadar ... kar tanesi düşecek.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Tahmin: Saat 17.00''ye kadar çok kar tanesi düşecek.'::text),
(317835,35315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előrejelzés: 17 óráig ... hópehely fog hullani.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Előrejelzés: 17 óráig sok hópehely fog hullani.'::text),
(317838,35316,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf ihrem Fäustling ... Schneeflocken, weil es schneit.'::text,'sind'::text,'ist'::text,'sein'::text,'Auf ihrem Fäustling sind Schneeflocken, weil es schneit.'::text),
(317842,35316,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На її рукавиці ... сніжинки, бо йде сніг.'::text,'є'::text,'є'::text,'бути'::text,'На її рукавиці є сніжинки, бо йде сніг.'::text),
(317841,35316,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... copos de nieve en su manopla porque está nevando.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay copos de nieve en su manopla porque está nevando.'::text),
(317840,35316,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des flocons sur sa moufle parce qu''il neige.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des flocons sur sa moufle parce qu''il neige.'::text),
(317843,35316,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kar yağdığı için eldiveninde kar taneleri ...'::text,'var'::text,'var'::text,'olmak'::text,'Kar yağdığı için eldiveninde kar taneleri var.'::text),
(317844,35316,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kesztyűjén hópelyhek ..., mert havazik.'::text,'vannak'::text,'van'::text,'lenni'::text,'A kesztyűjén hópelyhek vannak, mert havazik.'::text),
(317856,35318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... diese Schneeflocken filmen. Das ist so charmant.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Ehrlich, du solltest diese Schneeflocken filmen. Das ist so charmant.'::text),
(317860,35318,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... зняти ці сніжинки. Це так мило.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Чесно, ти мала б зняти ці сніжинки. Це так мило.'::text),
(317859,35318,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... grabar estos copos. Es tan encantador.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'La verdad, deberías grabar estos copos. Es tan encantador.'::text),
(317858,35318,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... filmer ces flocons. C''est tellement charmant.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Franchement, tu devrais filmer ces flocons. C''est tellement charmant.'::text),
(317861,35318,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bu kar tanelerini ...! Çok büyüleyici.'::text,'çekmelisin'::text,'çekmelisin'::text,'çekmelisin'::text,'Açıkçası bu kar tanelerini çekmelisin! Çok büyüleyici.'::text),
