(320889,35655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Tür und sieht die Sonnenblumen.'::text,'öffnet'::text,'öffnen'::text,'öffnend'::text,'Sie öffnet die Tür und sieht die Sonnenblumen.'::text),
(320893,35655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... двері й бачить соняшники.'::text,'відчиняє'::text,'відчиняти'::text,'відчиняючи'::text,'Вона відчиняє двері й бачить соняшники.'::text),
