(320891,35655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la porte et voit les tournesols.'::text,'ouvre'::text,'ouvrir'::text,'ouvrant'::text,'Elle ouvre la porte et voit les tournesols.'::text),
(320894,35655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapıyı ... ve ayçiçeklerini görür.'::text,'açar'::text,'açmak'::text,'açarak'::text,'Kapıyı açar ve ayçiçeklerini görür.'::text),
(320895,35655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... az ajtót, és meglátja a napraforgókat.'::text,'Kinyitja'::text,'Kinyitni'::text,'Kinyitó'::text,'Kinyitja az ajtót, és meglátja a napraforgókat.'::text),
(320907,35657,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bringst ... an meine Tür? Echt charmant.'::text,'12 Sonnenblumen'::text,'12 Sonnenblume'::text,'12 Sonnenblumen'::text,'Du bringst 12 Sonnenblumen an meine Tür? Echt charmant.'::text),
(320911,35657,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти приносиш ... до моїх дверей? Чесно, мило.'::text,'12 соняшників'::text,'12 соняшник'::text,'12 соняшників'::text,'Ти приносиш 12 соняшників до моїх дверей? Чесно, мило.'::text),
(320910,35657,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Me traes ... a la puerta? Qué encanto, la verdad.'::text,'12 girasoles'::text,'12 girasol'::text,'12 girasoles'::text,'¿Me traes 12 girasoles a la puerta? Qué encanto, la verdad.'::text),
(320909,35657,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu apportes ... à ma porte ? Franchement charmant.'::text,'12 tournesols'::text,'12 tournesol'::text,'12 tournesols'::text,'Tu apportes 12 tournesols à ma porte ? Franchement charmant.'::text),
