(320918,35658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un homme apporte des tournesols. Elle prend ... tournesols dans ses bras.'::text,'les'::text,'un'::text,'un'::text,'Un homme apporte des tournesols. Elle prend les tournesols dans ses bras.'::text),
