(320925,35659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schaut ... großen gelben Sonnenblumen in ihren Armen an.'::text,'diese'::text,'diese'::text,'jene'::text,'Sie schaut diese großen gelben Sonnenblumen in ihren Armen an.'::text),
