(318561,35396,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... habla? En una gran plaza de la ciudad.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde habla? En una gran plaza de la ciudad.'::text),
(318560,35396,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... parle-t-elle ? Sur une grande place de la ville.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où parle-t-elle ? Sur une grande place de la ville.'::text),
(318563,35396,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... konuşuyor? Büyük bir şehir meydanında.'::text,'Nerede'::text,'Ne zaman'::text,'Kim'::text,'Nerede konuşuyor? Büyük bir şehir meydanında.'::text),
(318564,35396,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... beszél? Egy nagy városi téren.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol beszél? Egy nagy városi téren.'::text),
(318576,35398,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Agenda: Um 15 Uhr ... sie wieder zur Menge sprechen.'::text,'wird'::text,'wird'::text,NULL::text,'Agenda: Um 15 Uhr wird sie wieder zur Menge sprechen.'::text),
(318580,35398,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Порядок денний: о 15:00 вона ... знову говорити до натовпу.'::text,'збирається'::text,'буде'::text,NULL::text,'Порядок денний: о 15:00 вона збирається знову говорити до натовпу.'::text),
(318579,35398,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Agenda: a las 15:00 ... hablar de nuevo ante la multitud.'::text,'va a'::text,NULL::text,NULL::text,'Agenda: a las 15:00 va a hablar de nuevo ante la multitud.'::text),
(318578,35398,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Programme : à 15 h, elle ... parler de nouveau à la foule.'::text,'va'::text,NULL::text,NULL::text,'Programme : à 15 h, elle va parler de nouveau à la foule.'::text),
(318581,35398,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gündem: Saat 15.00''te kalabalığa yeniden ...'::text,'konuşacak'::text,'konuşacak'::text,NULL::text,'Gündem: Saat 15.00''te kalabalığa yeniden konuşacak.'::text),
(318582,35398,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napirend: 15 órakor újra ... beszélni a tömeghez.'::text,'fog'::text,'fog'::text,NULL::text,'Napirend: 15 órakor újra fog beszélni a tömeghez.'::text),
(318585,35399,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mikrofon ist zum Sprechen da, also ... sie hineinsprechen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Das Mikrofon ist zum Sprechen da, also muss sie hineinsprechen.'::text),
(318589,35399,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мікрофон для того, щоб говорити, тож вона ... говорити в нього.'::text,'має'::text,'мусить'::text,'мала б'::text,'Мікрофон для того, щоб говорити, тож вона має говорити в нього.'::text),
(318588,35399,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El micrófono es para hablar, así que ... hablar por él.'::text,'tiene que'::text,'debe'::text,'debería'::text,'El micrófono es para hablar, así que tiene que hablar por él.'::text),
(318587,35399,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le micro sert à parler, donc elle ... parler dedans.'::text,'doit'::text,'doit'::text,'devrait'::text,'Le micro sert à parler, donc elle doit parler dedans.'::text),
(318590,35399,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mikrofon konuşmak için, bu yüzden mikrofona ...'::text,'konuşmak zorunda'::text,'konuşmalı'::text,'konuşmalı'::text,'Mikrofon konuşmak için, bu yüzden mikrofona konuşmak zorunda.'::text),
(318591,35399,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mikrofon beszédre való, ezért bele ... beszélnie.'::text,'kell'::text,'kell'::text,'kellene'::text,'A mikrofon beszédre való, ezért bele kell beszélnie.'::text),
(318594,35400,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alle filmen! Sie ... laut sprechen, sonst ist es aus!'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Alle filmen! Sie sollte laut sprechen, sonst ist es aus!'::text),
(318598,35400,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі знімають! Вона ... говорити голосно, інакше кінець!'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Усі знімають! Вона мала б говорити голосно, інакше кінець!'::text),
(318597,35400,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Todos están grabando! ¡... hablar alto o es el fin!'::text,'Debería'::text,'Debería'::text,'Debería'::text,'¡Todos están grabando! ¡Debería hablar alto o es el fin!'::text),
(318596,35400,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le monde filme ! Elle ... parler fort, sinon c''est la fin !'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Tout le monde filme ! Elle devrait parler fort, sinon c''est la fin !'::text),
(318599,35400,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herkes çekiyor! Yüksek sesle ..., yoksa her şey biter!'::text,'konuşmalı'::text,'konuşmalı'::text,'konuşmalı'::text,'Herkes çekiyor! Yüksek sesle konuşmalı, yoksa her şey biter!'::text),
(318600,35400,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindenki filmez! Hangosan ... beszélnie, különben vége!'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Mindenki filmez! Hangosan kellene beszélnie, különben vége!'::text),
(318603,35401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge klatscht wie verrückt, ... sie so gut spricht! Totales Chaos!'::text,'weil'::text,'aber'::text,'also'::text,'Die Menge klatscht wie verrückt, weil sie so gut spricht! Totales Chaos!'::text),
(318607,35401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп шалено аплодує, ... вона так добре говорить! Повний хаос!'::text,'бо'::text,'але'::text,'тому'::text,'Натовп шалено аплодує, бо вона так добре говорить! Повний хаос!'::text),
(318606,35401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La multitud aplaude como loca ... habla tan bien! ¡Caos absoluto!'::text,'porque'::text,'pero'::text,'así que'::text,'¡La multitud aplaude como loca porque habla tan bien! ¡Caos absoluto!'::text),
(318605,35401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule applaudit à tout rompre ... elle parle si bien ! Chaos total !'::text,'parce qu'''::text,'mais'::text,'donc'::text,'La foule applaudit à tout rompre parce qu'' elle parle si bien ! Chaos total !'::text),
(318608,35401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık çılgınca alkışlıyor ... çok iyi konuşuyor! Tam bir kaos!'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Kalabalık çılgınca alkışlıyor çünkü çok iyi konuşuyor! Tam bir kaos!'::text),
(318609,35401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tömeg őrülten tapsol, ... olyan jól beszél! Teljes káosz!'::text,'mert'::text,'de'::text,'ezért'::text,'A tömeg őrülten tapsol, mert olyan jól beszél! Teljes káosz!'::text),
(316929,35215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er läuft sonst langsam Schlittschuh, aber gestern ... er sehr schnell.'::text,'lief'::text,'läuft'::text,NULL::text,'Er läuft sonst langsam Schlittschuh, aber gestern lief er sehr schnell.'::text),
(316933,35215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зазвичай катається повільно, але вчора ... дуже швидко.'::text,'катався'::text,'катається'::text,NULL::text,'Він зазвичай катається повільно, але вчора катався дуже швидко.'::text),
(316932,35215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente patina despacio, pero ayer ... muy rápido.'::text,'patinó'::text,'patina'::text,NULL::text,'Normalmente patina despacio, pero ayer patinó muy rápido.'::text),
(316931,35215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il patine lentement, mais hier il ... très vite.'::text,'a patiné'::text,'patine'::text,NULL::text,'D''habitude il patine lentement, mais hier il a patiné très vite.'::text),
(316934,35215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde yavaş kayar ama dün çok hızlı ...'::text,'kaydı'::text,'kayar'::text,NULL::text,'Genelde yavaş kayar ama dün çok hızlı kaydı.'::text),
(316935,35215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában lassan korcsolyázik, de tegnap nagyon gyorsan ...'::text,'korcsolyázott'::text,'korcsolyázik'::text,NULL::text,'Általában lassan korcsolyázik, de tegnap nagyon gyorsan korcsolyázott.'::text),
(316938,35216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... gerade so geschmeidig übers Eis.'::text,'gleitest'::text,'gleitest'::text,'gleitet'::text,'Ehrlich, du gleitest gerade so geschmeidig übers Eis.'::text),
(316942,35216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти зараз так плавно ... по льоду.'::text,'ковзаєш'::text,'ковзаєш'::text,'ковзає'::text,'Чесно, ти зараз так плавно ковзаєш по льоду.'::text),
(316941,35216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ahora mismo ... tan suave sobre el hielo.'::text,'estás patinando'::text,'patinas'::text,'está patinando'::text,'La verdad, ahora mismo estás patinando tan suave sobre el hielo.'::text),
(316940,35216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, là tu ... si gracieusement sur la glace.'::text,'es en train de patiner'::text,'patines'::text,'est en train de patiner'::text,'Franchement, là tu es en train de patiner si gracieusement sur la glace.'::text),
(316943,35216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası şu an buzun üstünde çok akıcı ...'::text,'kayıyorsun'::text,'kayarsın'::text,'kayıyor'::text,'Açıkçası şu an buzun üstünde çok akıcı kayıyorsun.'::text),
(316944,35216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, most olyan simán ... a jégen.'::text,'korcsolyázol'::text,'korcsolyázol'::text,'korcsolyázik'::text,'Őszintén, most olyan simán korcsolyázol a jégen.'::text),
(316956,35218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Null Schwindel, klar: Er ... in einer geraden Linie Schlittschuh laufen.'::text,'wird'::text,'wird'::text,'wird'::text,'Null Schwindel, klar: Er wird in einer geraden Linie Schlittschuh laufen.'::text),
(316960,35218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жодного запаморочення, звісно: він ... кататися по прямій.'::text,'буде'::text,'буде'::text,'буде'::text,'Жодного запаморочення, звісно: він буде кататися по прямій.'::text),
(316959,35218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nada de mareos, claro: ... patinar en línea recta.'::text,''::text,NULL::text,NULL::text,'Nada de mareos, claro: patinar en línea recta.'::text),
(316958,35218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aucun vertige, évidemment : il ... patiner en ligne droite.'::text,''::text,NULL::text,NULL::text,'Aucun vertige, évidemment : il patiner en ligne droite.'::text),
(316961,35218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç baş dönmesi yok, tabii ki: düz bir çizgide ...'::text,'kayacak'::text,'kayacak'::text,'kayacak'::text,'Hiç baş dönmesi yok, tabii ki: düz bir çizgide kayacak.'::text),
(316962,35218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Semmi szédülés, persze: egyenes vonalban ... korcsolyázni.'::text,'fog'::text,'fog'::text,'fog'::text,'Semmi szédülés, persze: egyenes vonalban fog korcsolyázni.'::text),
(316965,35219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genialer Plan, klar: Er ... gleichzeitig Schlittschuh laufen und sich drehen.'::text,'wird'::text,'werden'::text,'wird'::text,'Genialer Plan, klar: Er wird gleichzeitig Schlittschuh laufen und sich drehen.'::text),
(316969,35219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Геніальний план, ясно: він ... кататися й крутитися одночасно.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Геніальний план, ясно: він збирається кататися й крутитися одночасно.'::text),
(316968,35219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan genial, está claro: ... patinar y girar a la vez.'::text,'va a'::text,'van a'::text,'va a'::text,'Plan genial, está claro: va a patinar y girar a la vez.'::text),
(316967,35219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan génial, clairement : il ... patiner et tourner en même temps.'::text,'va'::text,'vont'::text,'va'::text,'Plan génial, clairement : il va patiner et tourner en même temps.'::text),
(316970,35219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dahice plan, belli ki: aynı anda kayıp ...'::text,'dönecek'::text,'dönecekler'::text,'dönecek'::text,'Dahice plan, belli ki: aynı anda kayıp dönecek.'::text),
(316971,35219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zseniális terv, egyértelműen: egyszerre ... korcsolyázni és pörögni.'::text,'fog'::text,'fognak'::text,'fog'::text,'Zseniális terv, egyértelműen: egyszerre fog korcsolyázni és pörögni.'::text),
(316974,35220,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, klar: Er verspricht: „Ich ... Schlittschuh laufen, ohne hinzufallen.“'::text,'werde'::text,'werde'::text,NULL::text,'Super gemacht, klar: Er verspricht: „Ich werde Schlittschuh laufen, ohne hinzufallen.“'::text),
(316978,35220,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, звісно: він обіцяє: «Я ... кататися без падінь».'::text,'буду'::text,'збираюся'::text,NULL::text,'Чудова робота, звісно: він обіцяє: «Я буду кататися без падінь».'::text),
(316977,35220,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, claro: promete: «... patinar sin caerme».'::text,''::text,'Voy a'::text,NULL::text,'Buen trabajo, claro: promete: « patinar sin caerme».'::text),
(316976,35220,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, évidemment : il promet : « Je ... patiner sans tomber. »'::text,''::text,'vais'::text,NULL::text,'Bravo, évidemment : il promet : « Je patiner sans tomber. »'::text),
(316979,35220,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, tabii ki: “Düşmeden ...” diye söz veriyor.'::text,'kayacağım'::text,'kayacağım'::text,NULL::text,'Harika iş, tabii ki: “Düşmeden kayacağım” diye söz veriyor.'::text),
(316980,35220,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, persze: megígéri: „Esés nélkül ... korcsolyázni.”'::text,'fogok'::text,'fogok'::text,NULL::text,'Szép munka, persze: megígéri: „Esés nélkül fogok korcsolyázni.”'::text),
(316983,35221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Die Eisbahn schließt in fünf Minuten. Er ... jetzt Schlittschuh laufen!'::text,'muss'::text,'muss'::text,'sollte'::text,'Katastrophe! Die Eisbahn schließt in fünf Minuten. Er muss jetzt Schlittschuh laufen!'::text),
(316987,35221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Ковзанка зачиняється за п''ять хвилин. Він ... кататися зараз!'::text,'має'::text,'мусить'::text,'мав би'::text,'Катастрофа! Ковзанка зачиняється за п''ять хвилин. Він має кататися зараз!'::text),
(316986,35221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! La pista cierra en cinco minutos. ¡... patinar ya!'::text,'Tiene que'::text,'Debe'::text,'Debería'::text,'¡Desastre! La pista cierra en cinco minutos. ¡Tiene que patinar ya!'::text),
(316985,35221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! La patinoire ferme dans cinq minutes. Il ... patiner maintenant !'::text,'doit'::text,'doit'::text,'devrait'::text,'Catastrophe ! La patinoire ferme dans cinq minutes. Il doit patiner maintenant !'::text),
(316988,35221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Buz pisti beş dakika içinde kapanıyor. Hemen ...!'::text,'kaymak zorunda'::text,'kaymalı'::text,'kaymalı'::text,'Felaket! Buz pisti beş dakika içinde kapanıyor. Hemen kaymak zorunda!'::text),
(316989,35221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Öt perc múlva bezár a jégpálya. Most ... korcsolyáznia!'::text,'kell'::text,'kell'::text,'kellene'::text,'Katasztrófa! Öt perc múlva bezár a jégpálya. Most kell korcsolyáznia!'::text),
(316992,35222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Eis ist hart, also ... er vorsichtig Schlittschuh laufen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Das Eis ist hart, also sollte er vorsichtig Schlittschuh laufen.'::text),
(316996,35222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лід твердий, тож він ... кататися обережно.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Лід твердий, тож він мав би кататися обережно.'::text),
(316995,35222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hielo está duro, así que ... patinar con cuidado.'::text,'debería'::text,'debería'::text,'debería'::text,'El hielo está duro, así que debería patinar con cuidado.'::text),
(316994,35222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La glace est dure, alors il ... patiner prudemment.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'La glace est dure, alors il devrait patiner prudemment.'::text),
(316997,35222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buz sert, bu yüzden dikkatli ...'::text,'kaymalı'::text,'kaymalı'::text,'kaymalı'::text,'Buz sert, bu yüzden dikkatli kaymalı.'::text),
(316998,35222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kemény a jég, ezért óvatosan ... korcsolyáznia.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Kemény a jég, ezért óvatosan kellene korcsolyáznia.'::text),
(319746,35528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... einen riesigen Stein. Wirft er ihn gleich?'::text,'hat'::text,'haben'::text,'hat'::text,'Alter, er hat einen riesigen Stein. Wirft er ihn gleich?'::text),
(319750,35528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... величезний камінь. Кине його?'::text,'має'::text,'мати'::text,'має'::text,'Бро, він має величезний камінь. Кине його?'::text),
(319749,35528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... una piedra enorme. ¿La va a tirar?'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Tío, tiene una piedra enorme. ¿La va a tirar?'::text),
(319748,35528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... une énorme pierre. Il va la lancer ?'::text,'a'::text,'ont'::text,'a'::text,'Mec, il a une énorme pierre. Il va la lancer ?'::text),
(319751,35528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, elinde kocaman bir taş ..., fırlatacak mı?'::text,'var'::text,'var'::text,'var'::text,'Kanka, elinde kocaman bir taş var, fırlatacak mı?'::text),
(319752,35528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... egy óriási köve. Eldobja?'::text,'van'::text,'van'::text,'van'::text,'Tesó, van egy óriási köve. Eldobja?'::text),
(319755,35529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er braucht ... für einen größeren Platscher.'::text,'2 Steine'::text,'2 Stein'::text,'2 Steine'::text,'Alter, er braucht 2 Steine für einen größeren Platscher.'::text),
(319759,35529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, йому знадобиться ... для більшого сплеску.'::text,'2 камені'::text,'2 камінь'::text,'2 камені'::text,'Бро, йому знадобиться 2 камені для більшого сплеску.'::text),
