(319757,35529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il va lui falloir ... pour une plus grosse gerbe d''eau.'::text,'2 pierres'::text,'2 pierre'::text,'2 pierres'::text,'Mec, il va lui falloir 2 pierres pour une plus grosse gerbe d''eau.'::text),
