(319761,35529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egy nagyobb csobbanáshoz ... kell majd neki.'::text,'2 kő'::text,'2 kő'::text,'2 kő'::text,'Tesó, egy nagyobb csobbanáshoz 2 kő kell majd neki.'::text),
(319764,35530,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Das graue Objekt auf dem Steg ist ... Stein von 20 Kilo.'::text,'ein'::text,'ein'::text,'der'::text,'Bericht: Das graue Objekt auf dem Steg ist ein Stein von 20 Kilo.'::text),
