(319767,35530,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: el objeto gris del embarcadero es ... piedra de 20 kilos.'::text,'una'::text,'una'::text,'la'::text,'Informe: el objeto gris del embarcadero es una piedra de 20 kilos.'::text),
(319766,35530,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : l''objet gris sur le ponton est ... pierre de 20 kilos.'::text,'une'::text,'une'::text,'la'::text,'Rapport : l''objet gris sur le ponton est une pierre de 20 kilos.'::text),
(319769,35530,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: İskeledeki gri nesne 20 kiloluk ... taş.'::text,'bir'::text,'bir'::text,NULL::text,'Rapor: İskeledeki gri nesne 20 kiloluk bir taş.'::text),
(319770,35530,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: a stégen lévő szürke tárgy ... 20 kilós kő.'::text,'egy'::text,'egy'::text,'a'::text,'Jelentés: a stégen lévő szürke tárgy egy 20 kilós kő.'::text),
(319773,35531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Stein ist schwer, weil er ein großer Stein ist.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Stein ist schwer, weil er ein großer Stein ist.'::text),
(319777,35531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... камінь важкий, бо це великий камінь.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей камінь важкий, бо це великий камінь.'::text),
(319776,35531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... piedra pesa porque es una piedra grande.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta piedra pesa porque es una piedra grande.'::text),
(319775,35531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pierre est lourde parce que c''est une grosse pierre.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette pierre est lourde parce que c''est une grosse pierre.'::text),
(319778,35531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... taş ağır çünkü büyük bir taş.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu taş ağır çünkü büyük bir taş.'::text),
(319779,35531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a kő nehéz, mert nagy kő.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a kő nehéz, mert nagy kő.'::text),
(319791,35533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der große Stein schleudert eine Menge ... in die Luft.'::text,'Wasser'::text,'Wasser'::text,'ein Wasser'::text,'Der große Stein schleudert eine Menge Wasser in die Luft.'::text),
(319795,35533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Великий камінь підкидає в повітря багато ...'::text,'води'::text,'вод'::text,'води'::text,'Великий камінь підкидає в повітря багато води.'::text),
(319794,35533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gran piedra lanza mucha ... al aire.'::text,'agua'::text,'agua'::text,'un agua'::text,'La gran piedra lanza mucha agua al aire.'::text),
(319793,35533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La grosse pierre projette beaucoup ... en l''air.'::text,'d''eau'::text,'d''eau'::text,'d''une eau'::text,'La grosse pierre projette beaucoup d''eau en l''air.'::text),
(319796,35533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük taş havaya çok ... sıçratıyor.'::text,'su'::text,'sular'::text,'bir su'::text,'Büyük taş havaya çok su sıçratıyor.'::text),
(319797,35533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy kő rengeteg ... fröcsköl a levegőbe.'::text,'vizet'::text,'vizet'::text,'egy vizet'::text,'A nagy kő rengeteg vizet fröcsköl a levegőbe.'::text),
(319800,35534,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie ... Steine liegen auf dem Steg? Nur einer.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Wie viele Steine liegen auf dem Steg? Nur einer.'::text),
(319804,35534,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... каменів на пристані? Лише один.'::text,'Скільки'::text,'Скільки'::text,'Будь-яких'::text,'Скільки каменів на пристані? Лише один.'::text),
(319803,35534,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... piedras hay en el embarcadero? Solo una.'::text,'Cuántas'::text,'Cuánta'::text,'Cualquier'::text,'¿Cuántas piedras hay en el embarcadero? Solo una.'::text),
(319802,35534,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pierres y a-t-il sur le ponton ? Une seule.'::text,'Combien de'::text,'Combien de'::text,'N''importe quelles'::text,'Combien de pierres y a-t-il sur le ponton ? Une seule.'::text),
(319805,35534,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İskelede ... taş var? Sadece bir tane.'::text,'kaç'::text,'kaç'::text,'herhangi bir'::text,'İskelede kaç taş var? Sadece bir tane.'::text),
