(318720,35414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Sie ... nur einen kleinen Schwamm für diese Pfanne!'::text,'hat'::text,'haben'::text,'hat'::text,'Albtraum! Sie hat nur einen kleinen Schwamm für diese Pfanne!'::text),
(318724,35414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Вона ... лише одну маленьку губку для цієї сковорідки!'::text,'має'::text,'мати'::text,'має'::text,'Жах! Вона має лише одну маленьку губку для цієї сковорідки!'::text),
(318723,35414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Solo ... una esponjita para esta sartén!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Pesadilla! ¡Solo tiene una esponjita para esta sartén!'::text),
(318722,35414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Elle ... seulement une petite éponge pour cette poêle !'::text,'a'::text,'ont'::text,'a'::text,'Cauchemar ! Elle a seulement une petite éponge pour cette poêle !'::text),
(318725,35414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bu tava için sadece bir tane küçük süngeri ...!'::text,'var'::text,'var'::text,'var'::text,'Kâbus! Bu tava için sadece bir tane küçük süngeri var!'::text),
(318726,35414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Csak egy kis szivacsa ... ehhez a serpenyőhöz!'::text,'van'::text,'van'::text,'van'::text,'Rémálom! Csak egy kis szivacsa van ehhez a serpenyőhöz!'::text),
(318729,35415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... diese schreckliche Pfanne mit ihrem Schwamm! Totaler Krieg!'::text,'schrubbt'::text,'schrubben'::text,'schrubbend'::text,'Sie schrubbt diese schreckliche Pfanne mit ihrem Schwamm! Totaler Krieg!'::text),
(318733,35415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... цю жахливу сковорідку своєю губкою! Тотальна війна!'::text,'тре'::text,'терти'::text,'тручи'::text,'Вона тре цю жахливу сковорідку своєю губкою! Тотальна війна!'::text),
(318732,35415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... esta horrible sartén con su esponja! ¡Guerra total!'::text,'friega'::text,'fregar'::text,'fregando'::text,'¡Ella friega esta horrible sartén con su esponja! ¡Guerra total!'::text),
(318731,35415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... cette horrible poêle avec son éponge ! Guerre totale !'::text,'frotte'::text,'frotter'::text,'frottant'::text,'Elle frotte cette horrible poêle avec son éponge ! Guerre totale !'::text),
(318734,35415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu korkunç tavayı süngeriyle ...! Topyekûn savaş!'::text,'ovalar'::text,'ovalamak'::text,'ovalayarak'::text,'Bu korkunç tavayı süngeriyle ovalar! Topyekûn savaş!'::text),
(318735,35415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ezt a szörnyű serpenyőt a szivacsával! Totális háború!'::text,'Súrolja'::text,'Súrolni'::text,'Súroló'::text,'Súrolja ezt a szörnyű serpenyőt a szivacsával! Totális háború!'::text),
(318738,35416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schwamm ist weich, aber er ... die schmutzige Pfanne sauber machen.'::text,'kann'::text,'kann'::text,NULL::text,'Der Schwamm ist weich, aber er kann die schmutzige Pfanne sauber machen.'::text),
(318742,35416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Губка м''яка, але вона ... відчистити брудну сковорідку.'::text,'може'::text,'може'::text,NULL::text,'Губка м''яка, але вона може відчистити брудну сковорідку.'::text),
(318741,35416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La esponja es blanda, pero ... limpiar la sartén sucia.'::text,'puede'::text,'puede'::text,NULL::text,'La esponja es blanda, pero puede limpiar la sartén sucia.'::text),
(318740,35416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''éponge est douce, mais elle ... nettoyer la poêle sale.'::text,'peut'::text,'peut'::text,NULL::text,'L''éponge est douce, mais elle peut nettoyer la poêle sale.'::text),
(318743,35416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sünger yumuşak ama kirli tavayı ...'::text,'temizleyebilir'::text,'temizleyebilir'::text,NULL::text,'Sünger yumuşak ama kirli tavayı temizleyebilir.'::text),
(318744,35416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szivacs puha, de ki ... tisztítani a koszos serpenyőt.'::text,'tudja'::text,'tudja'::text,NULL::text,'A szivacs puha, de ki tudja tisztítani a koszos serpenyőt.'::text),
(318756,35418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie benutzt einen Schwamm für ... Pfanne, nicht für zwei.'::text,'eine'::text,'erste'::text,'einmal'::text,'Sie benutzt einen Schwamm für eine Pfanne, nicht für zwei.'::text),
(318760,35418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона використовує одну губку на ... сковорідку, а не на дві.'::text,'одну'::text,'першу'::text,'раз'::text,'Вона використовує одну губку на одну сковорідку, а не на дві.'::text),
(318759,35418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Usa una esponja para ... sartén, no para dos.'::text,'una'::text,'primera'::text,'una vez'::text,'Usa una esponja para una sartén, no para dos.'::text),
(318758,35418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle utilise une éponge pour ... poêle, pas pour deux.'::text,'une'::text,'première'::text,'une fois'::text,'Elle utilise une éponge pour une poêle, pas pour deux.'::text),
(318761,35418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki değil, ... tava için bir sünger kullanıyor.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'İki değil, bir tava için bir sünger kullanıyor.'::text),
(318762,35418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy szivacsot használ ... serpenyőhöz, nem kettőhöz.'::text,'egy'::text,'első'::text,'egyszer'::text,'Egy szivacsot használ egy serpenyőhöz, nem kettőhöz.'::text),
(318774,35420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine Kritik: Da ist so ... Soße und nur ein Schwamm.'::text,'viel'::text,'viele'::text,'irgendwelche'::text,'Keine Kritik: Da ist so viel Soße und nur ein Schwamm.'::text),
(318778,35420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Без зауважень: тут так ... соусу, і лише одна губка.'::text,'багато'::text,'багато'::text,'будь-якого'::text,'Без зауважень: тут так багато соусу, і лише одна губка.'::text),
(318777,35420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sin pegas: hay ... salsa, y solo una esponja.'::text,'tanta'::text,'tantas'::text,'cualquier'::text,'Sin pegas: hay tanta salsa, y solo una esponja.'::text),
(318776,35420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rien à redire : il y a ... sauce, et une seule éponge.'::text,'tellement de'::text,'tellement de'::text,'n''importe quelle'::text,'Rien à redire : il y a tellement de sauce, et une seule éponge.'::text),
(318779,35420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç itirazım yok: o kadar ... sos var ve sadece bir sünger.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Hiç itirazım yok: o kadar çok sos var ve sadece bir sünger.'::text),
(318780,35420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Semmi kifogás: olyan ... szósz van, és csak egy szivacs.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Semmi kifogás: olyan sok szósz van, és csak egy szivacs.'::text),
(318783,35421,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich das perfekte Werkzeug: Da ... ein kleiner Schwamm für diese riesige Pfanne.'::text,'ist'::text,'sind'::text,'sein'::text,'Offensichtlich das perfekte Werkzeug: Da ist ein kleiner Schwamm für diese riesige Pfanne.'::text),
(318787,35421,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, ідеальний інструмент: на цю величезну сковорідку ... одна маленька губка.'::text,'є'::text,'є'::text,'бути'::text,'Очевидно, ідеальний інструмент: на цю величезну сковорідку є одна маленька губка.'::text),
(318786,35421,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, la herramienta perfecta: ... una esponjita para esta sartén enorme.'::text,'hay'::text,'hay'::text,'hay'::text,'Obviamente, la herramienta perfecta: hay una esponjita para esta sartén enorme.'::text),
(318785,35421,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment l''outil parfait : ... une petite éponge pour cette énorme poêle.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Évidemment l''outil parfait : il y a une petite éponge pour cette énorme poêle.'::text),
(318788,35421,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki mükemmel alet: bu dev tava için tek bir küçük sünger ...'::text,'var'::text,'var'::text,'olmak'::text,'Belli ki mükemmel alet: bu dev tava için tek bir küçük sünger var.'::text),
(318789,35421,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván a tökéletes eszköz: egy kis szivacs ... ehhez az óriási serpenyőhöz.'::text,'van'::text,'vannak'::text,'lenni'::text,'Nyilván a tökéletes eszköz: egy kis szivacs van ehhez az óriási serpenyőhöz.'::text),
(314877,34987,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das kleine blasse Ding in seiner Hand ist ... Samen.'::text,'ein'::text,'ein'::text,'der'::text,'Das kleine blasse Ding in seiner Hand ist ein Samen.'::text),
(314881,34987,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленька бліда штучка в його руці — ... насінина.'::text,''::text,NULL::text,NULL::text,'Маленька бліда штучка в його руці — насінина.'::text),
(314880,34987,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cosita pálida de su mano es ... semilla.'::text,'una'::text,'una'::text,'la'::text,'La cosita pálida de su mano es una semilla.'::text),
(314879,34987,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La petite chose pâle dans sa main est ... graine.'::text,'une'::text,'une'::text,'la'::text,'La petite chose pâle dans sa main est une graine.'::text),
(314882,34987,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elindeki küçük soluk şey ... tohum.'::text,'bir'::text,'bir'::text,NULL::text,'Elindeki küçük soluk şey bir tohum.'::text),
(314883,34987,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kezében lévő kicsi, sápadt dolog ... mag.'::text,'egy'::text,'egy'::text,'a'::text,'A kezében lévő kicsi, sápadt dolog egy mag.'::text),
(314886,34988,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, ... Samen hat eine Wurzel! Der wird groß.'::text,'dieser'::text,'diese'::text,'jene'::text,'Alter, dieser Samen hat eine Wurzel! Der wird groß.'::text),
(314890,34988,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... насінина має корінець! Виросте великою.'::text,'ця'::text,'ці'::text,'ті'::text,'Бро, ця насінина має корінець! Виросте великою.'::text),
(314889,34988,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¡... semilla tiene una raíz! Va a crecer un montón.'::text,'esta'::text,'estas'::text,'esas'::text,'Tío, ¡esta semilla tiene una raíz! Va a crecer un montón.'::text),
(314888,34988,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, ... graine a une racine ! Elle va devenir énorme.'::text,'cette'::text,'ces'::text,'ces'::text,'Mec, cette graine a une racine ! Elle va devenir énorme.'::text),
(314891,34988,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... tohumun kökü var! Kocaman olacak.'::text,'bu'::text,'bu'::text,'şu'::text,'Kanka, bu tohumun kökü var! Kocaman olacak.'::text),
