(319442,35494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dors-tu ce soir ? Franchement, cette villa est trop cool.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où dors-tu ce soir ? Franchement, cette villa est trop cool.'::text),
(319445,35494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu gece ... kalıyorsun? Açıkçası o villa çok havalı.'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'Bu gece nerede kalıyorsun? Açıkçası o villa çok havalı.'::text),
(319446,35494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... alszol ma éjjel? Őszintén, az a villa nagyon menő.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol alszol ma éjjel? Őszintén, az a villa nagyon menő.'::text),
(319449,35495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzten Sommer ... du in einer Glasvilla. Ehrlich, so stilvoll.'::text,'wohntest'::text,'wohnst'::text,'wohnt'::text,'Letzten Sommer wohntest du in einer Glasvilla. Ehrlich, so stilvoll.'::text),
(319453,35495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулого літа ти ... у скляній віллі. Чесно, так стильно.'::text,'жив'::text,'живеш'::text,'живе'::text,'Минулого літа ти жив у скляній віллі. Чесно, так стильно.'::text),
(319452,35495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El verano pasado te ... en una villa de cristal. La verdad, qué clase.'::text,'alojaste'::text,'alojas'::text,'aloja'::text,'El verano pasado te alojaste en una villa de cristal. La verdad, qué clase.'::text),
(319451,35495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''été dernier, tu ... dans une villa en verre. Franchement, trop classe.'::text,'as logé'::text,'loges'::text,'loge'::text,'L''été dernier, tu as logé dans une villa en verre. Franchement, trop classe.'::text),
(319454,35495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen yaz cam bir villada ..., açıkçası çok şık.'::text,'kaldın'::text,'kalırsın'::text,'kalır'::text,'Geçen yaz cam bir villada kaldın, açıkçası çok şık.'::text),
(319455,35495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavaly nyáron ... egy üvegvillában. Őszintén, nagyon elegáns.'::text,'laktál'::text,'laksz'::text,'lakik'::text,'Tavaly nyáron laktál egy üvegvillában. Őszintén, nagyon elegáns.'::text),
(319458,35496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig geizig: Sie bleiben sonst zu Hause, aber letzten Sommer ... sie in einer Villa.'::text,'blieben'::text,'bleiben'::text,NULL::text,'Eindeutig geizig: Sie bleiben sonst zu Hause, aber letzten Sommer blieben sie in einer Villa.'::text),
(319462,35496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно скупі: вони зазвичай залишаються вдома, але минулого літа ... у віллі.'::text,'залишилися'::text,'залишаються'::text,NULL::text,'Явно скупі: вони зазвичай залишаються вдома, але минулого літа залишилися у віллі.'::text),
(319461,35496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente tacaños: normalmente se quedan en casa, pero el verano pasado se ... en una villa.'::text,'quedaron'::text,'quedan'::text,NULL::text,'Claramente tacaños: normalmente se quedan en casa, pero el verano pasado se quedaron en una villa.'::text),
(319460,35496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement radins : d''habitude ils restent à la maison, mais l''été dernier ils ... dans une villa.'::text,'sont restés'::text,'restent'::text,NULL::text,'Clairement radins : d''habitude ils restent à la maison, mais l''été dernier ils sont restés dans une villa.'::text),
(319463,35496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki cimri: genelde evde kalırlar ama geçen yaz bir villada ...'::text,'kaldılar'::text,'kalırlar'::text,NULL::text,'Belli ki cimri: genelde evde kalırlar ama geçen yaz bir villada kaldılar.'::text),
