(319476,35498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Hostel ist billig, also ... Backpacker dort übernachten.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Das Hostel ist billig, also sollten Backpacker dort übernachten.'::text),
