(319479,35498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El albergue es barato, así que los mochileros ... alojarse allí.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'El albergue es barato, así que los mochileros deberían alojarse allí.'::text),
(319478,35498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''auberge de jeunesse est bon marché, alors les routards ... y loger.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'L''auberge de jeunesse est bon marché, alors les routards devraient y loger.'::text),
