(319687,35521,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед обідом у нього ... порожній шлунок.'::text,''::text,NULL::text,NULL::text,'Перед обідом у нього порожній шлунок.'::text),
(319686,35521,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene ... estómago vacío antes de comer.'::text,'un'::text,'un'::text,'el'::text,'Tiene un estómago vacío antes de comer.'::text),
(319685,35521,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a ... estomac vide avant le déjeuner.'::text,'un'::text,'un'::text,'l'''::text,'Il a un estomac vide avant le déjeuner.'::text),
(319688,35521,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeğinden önce ... boş midesi var.'::text,'bir'::text,'bir'::text,NULL::text,'Öğle yemeğinden önce bir boş midesi var.'::text),
(319689,35521,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebéd előtt ... üres gyomra van.'::text,'egy'::text,'egy'::text,'az'::text,'Ebéd előtt egy üres gyomra van.'::text),
(319692,35522,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Magen ist leer! Das ist der schlimmste Tag überhaupt!'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Magen ist leer! Das ist der schlimmste Tag überhaupt!'::text),
(319696,35522,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... шлунок порожній! Це найгірший день у житті!'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей шлунок порожній! Це найгірший день у житті!'::text),
(319695,35522,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... estómago está vacío! ¡Es el peor día de mi vida!'::text,'Este'::text,'Estos'::text,'Esos'::text,'¡Este estómago está vacío! ¡Es el peor día de mi vida!'::text),
(319694,35522,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... estomac est vide ! C''est le pire jour de ma vie !'::text,'Cet'::text,'Ces'::text,'Ces'::text,'Cet estomac est vide ! C''est le pire jour de ma vie !'::text),
(319697,35522,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mide bomboş! Bu gelmiş geçmiş en kötü gün!'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu mide bomboş! Bu gelmiş geçmiş en kötü gün!'::text),
(319698,35522,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a gyomor üres! Ez minden idők legrosszabb napja!'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a gyomor üres! Ez minden idők legrosszabb napja!'::text),
(319710,35524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Magen tut ... 12 Uhr weh, vor dem Mittagessen.'::text,'um'::text,'am'::text,'im'::text,'Sein Magen tut um 12 Uhr weh, vor dem Mittagessen.'::text),
(319714,35524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його шлунок болить ... 12-й годині, перед обідом.'::text,'о'::text,'на'::text,'у'::text,'Його шлунок болить о 12-й годині, перед обідом.'::text),
(319713,35524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le duele el estómago ... las 12, antes de comer.'::text,'a'::text,'sobre'::text,'en'::text,'Le duele el estómago a las 12, antes de comer.'::text),
(319712,35524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a mal au ventre ... midi, avant le déjeuner.'::text,'à'::text,'sur'::text,'dans'::text,'Il a mal au ventre à midi, avant le déjeuner.'::text),
(319715,35524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeğinden önce, saat 12 ... midesi ağrıyor.'::text,''::text,NULL::text,NULL::text,'Öğle yemeğinden önce, saat 12 midesi ağrıyor.'::text),
(319716,35524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fáj a gyomra, ebéd előtt.'::text,'12 órakor'::text,'12 órán'::text,'12 órában'::text,'12 órakor fáj a gyomra, ebéd előtt.'::text),
(319719,35525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wartet zehn Minuten, und sein Magen ist ... Minuten lang leer.'::text,'zehn'::text,'zehnte'::text,'Zehnen'::text,'Er wartet zehn Minuten, und sein Magen ist zehn Minuten lang leer.'::text),
(319723,35525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він чекає десять хвилин, і його шлунок порожній ... хвилин.'::text,'десять'::text,'десятих'::text,'десятки'::text,'Він чекає десять хвилин, і його шлунок порожній десять хвилин.'::text),
(319722,35525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera diez minutos, y tiene el estómago vacío durante ... minutos.'::text,'diez'::text,'décimos'::text,'diez'::text,'Espera diez minutos, y tiene el estómago vacío durante diez minutos.'::text),
(319721,35525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il attend dix minutes, et son estomac est vide pendant ... minutes.'::text,'dix'::text,'dixièmes'::text,'dix'::text,'Il attend dix minutes, et son estomac est vide pendant dix minutes.'::text),
(319724,35525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakika bekliyor ve midesi ... dakika boyunca boş.'::text,'on'::text,'onuncu'::text,'onlar'::text,'On dakika bekliyor ve midesi on dakika boyunca boş.'::text),
(319725,35525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz percet vár, és a gyomra ... percig üres.'::text,'tíz'::text,'tizedik'::text,'tízesek'::text,'Tíz percet vár, és a gyomra tíz percig üres.'::text),
(319908,35546,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... den Verkehr gerade komplett zum Stehen. Stark.'::text,'bringst'::text,'bringst'::text,'bringt'::text,'Ehrlich, du bringst den Verkehr gerade komplett zum Stehen. Stark.'::text),
(319912,35546,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти саме зараз ... рух до повної зупинки. Круто.'::text,'доводиш'::text,'доводиш'::text,'доводить'::text,'Чесно, ти саме зараз доводиш рух до повної зупинки. Круто.'::text),
(319911,35546,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ahora mismo ... el tráfico por completo. Qué estilo.'::text,'estás deteniendo'::text,'detienes'::text,'está deteniendo'::text,'La verdad, ahora mismo estás deteniendo el tráfico por completo. Qué estilo.'::text),
(319910,35546,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, là tu ... la circulation à l''arrêt complet. Stylé.'::text,'es en train de mettre'::text,'mets'::text,'est en train de mettre'::text,'Franchement, là tu es en train de mettre la circulation à l''arrêt complet. Stylé.'::text),
(319913,35546,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası şu an trafiği tamamen durma noktasına ..., çok şık.'::text,'getiriyorsun'::text,'getirirsin'::text,'getiriyor'::text,'Açıkçası şu an trafiği tamamen durma noktasına getiriyorsun, çok şık.'::text),
(319914,35546,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, most teljesen megállásra ... a forgalmat. Ügyes.'::text,'kényszeríted'::text,'kényszeríted'::text,'kényszeríti'::text,'Őszintén, most teljesen megállásra kényszeríted a forgalmat. Ügyes.'::text),
(319917,35547,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stark! Du winkst sonst, aber jetzt ... du den Verkehr zum Stehen.'::text,'bringst'::text,'bringst'::text,NULL::text,'Stark! Du winkst sonst, aber jetzt bringst du den Verkehr zum Stehen.'::text),
(319921,35547,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круто! Ти зазвичай махаєш, але зараз ... рух до зупинки.'::text,'доводиш'::text,'доводиш'::text,NULL::text,'Круто! Ти зазвичай махаєш, але зараз доводиш рух до зупинки.'::text),
(319920,35547,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué estilo! Normalmente saludas con la mano, pero ahora ... el tráfico.'::text,'estás deteniendo'::text,'detienes'::text,NULL::text,'¡Qué estilo! Normalmente saludas con la mano, pero ahora estás deteniendo el tráfico.'::text),
(319919,35547,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stylé ! D''habitude tu fais signe, mais là tu ... la circulation à l''arrêt.'::text,'es en train de mettre'::text,'mets'::text,NULL::text,'Stylé ! D''habitude tu fais signe, mais là tu es en train de mettre la circulation à l''arrêt.'::text),
(319922,35547,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok şık! Genelde el sallarsın ama şimdi trafiği durma noktasına ...'::text,'getiriyorsun'::text,'getirirsin'::text,NULL::text,'Çok şık! Genelde el sallarsın ama şimdi trafiği durma noktasına getiriyorsun.'::text),
(319923,35547,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes! Általában integetsz, de most megállásra ... a forgalmat.'::text,'kényszeríted'::text,'kényszeríted'::text,NULL::text,'Ügyes! Általában integetsz, de most megállásra kényszeríted a forgalmat.'::text),
(319935,35549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entspannter Job, klar: Er ... für jeden Bus einen Stopp machen.'::text,'wird'::text,'werden'::text,'wird'::text,'Entspannter Job, klar: Er wird für jeden Bus einen Stopp machen.'::text),
(319939,35549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розслабна робота, звісно: він ... робити зупинку для кожного автобуса.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Розслабна робота, звісно: він збирається робити зупинку для кожного автобуса.'::text),
(319938,35549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trabajo relajado, claro: ... hacer una parada por cada autobús.'::text,'va a'::text,'van a'::text,'va a'::text,'Trabajo relajado, claro: va a hacer una parada por cada autobús.'::text),
(319937,35549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boulot tranquille, évidemment : il ... faire un arrêt pour chaque bus.'::text,'va'::text,'vont'::text,'va'::text,'Boulot tranquille, évidemment : il va faire un arrêt pour chaque bus.'::text),
(319940,35549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahat iş, tabii ki: her otobüs için bir duruş ...'::text,'yapacak'::text,'yapacaklar'::text,'yapacak'::text,'Rahat iş, tabii ki: her otobüs için bir duruş yapacak.'::text),
(319941,35549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyugis meló, persze: minden busznál ... tartani egy megállást.'::text,'fog'::text,'fognak'::text,'fog'::text,'Nyugis meló, persze: minden busznál fog tartani egy megállást.'::text),
(319944,35550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Total entspannend: Der Bus bremst hart, also ... er zum Stehen kommen.'::text,'wird'::text,'wird'::text,NULL::text,'Total entspannend: Der Bus bremst hart, also wird er zum Stehen kommen.'::text),
(319948,35550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цілком розслабно: автобус різко гальмує, тож він ... зупинитися.'::text,'збирається'::text,'буде'::text,NULL::text,'Цілком розслабно: автобус різко гальмує, тож він збирається зупинитися.'::text),
(319947,35550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Relajante total: el autobús frena en seco, así que ... detenerse.'::text,'va a'::text,NULL::text,NULL::text,'Relajante total: el autobús frena en seco, así que va a detenerse.'::text),
(319946,35550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totalement reposant : le bus freine fort, donc il ... s''arrêter.'::text,'va'::text,NULL::text,NULL::text,'Totalement reposant : le bus freine fort, donc il va s''arrêter.'::text),
(319949,35550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamamen rahatlatıcı: otobüs sert fren yapıyor, bu yüzden ...'::text,'duracak'::text,'duracak'::text,NULL::text,'Tamamen rahatlatıcı: otobüs sert fren yapıyor, bu yüzden duracak.'::text),
(319950,35550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen nyugis: a busz erősen fékez, így meg ... állni.'::text,'fog'::text,'fog'::text,NULL::text,'Teljesen nyugis: a busz erősen fékez, így meg fog állni.'::text),
(319953,35551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach dem Stopp ist hinter ihm eine Menge ...'::text,'Verkehr'::text,'Verkehr'::text,'ein Verkehr'::text,'Nach dem Stopp ist hinter ihm eine Menge Verkehr.'::text),
(319957,35551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після зупинки позаду нього багато ...'::text,'транспорту'::text,'транспорту'::text,'транспорту'::text,'Після зупинки позаду нього багато транспорту.'::text),
(319956,35551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de la parada, hay mucho ... detrás de él.'::text,'tráfico'::text,'tráfico'::text,'un tráfico'::text,'Después de la parada, hay mucho tráfico detrás de él.'::text),
(319955,35551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après l''arrêt, il y a beaucoup de ... derrière lui.'::text,'circulation'::text,'circulation'::text,'une circulation'::text,'Après l''arrêt, il y a beaucoup de circulation derrière lui.'::text),
(319958,35551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duruştan sonra arkasında çok fazla ... var.'::text,'trafik'::text,'trafikler'::text,'bir trafik'::text,'Duruştan sonra arkasında çok fazla trafik var.'::text),
(319959,35551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megállás után rengeteg ... van mögötte.'::text,'forgalom'::text,'forgalom'::text,'egy forgalom'::text,'A megállás után rengeteg forgalom van mögötte.'::text),
(319962,35552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stopp hält ... Autos und Motorroller hinter ihm auf.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Der Stopp hält viele Autos und Motorroller hinter ihm auf.'::text),
(319966,35552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зупинка тримає ... машин і скутерів позаду нього.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Зупинка тримає багато машин і скутерів позаду нього.'::text),
(319965,35552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La parada retiene ... coches y escúteres detrás de él.'::text,'muchos'::text,'mucho'::text,'cualquier'::text,'La parada retiene muchos coches y escúteres detrás de él.'::text),
(319964,35552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arrêt retient ... voitures et scooters derrière lui.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quelles'::text,'L''arrêt retient beaucoup de voitures et scooters derrière lui.'::text),
(319967,35552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duruş, arkasında ... araba ve scooter tutuyor.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Duruş, arkasında çok araba ve scooter tutuyor.'::text),
(319968,35552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A megállás ... autót és robogót tart fel mögötte.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'A megállás sok autót és robogót tart fel mögötte.'::text),
(319971,35553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... ein Stopp, weil die Autos sich nicht bewegen.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist ein Stopp, weil die Autos sich nicht bewegen.'::text),
(319975,35553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тут ... зупинка, бо машини не рухаються.'::text,'є'::text,'є'::text,'бути'::text,'Тут є зупинка, бо машини не рухаються.'::text),
(319974,35553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una parada porque los coches no se mueven.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una parada porque los coches no se mueven.'::text),
(319973,35553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un arrêt parce que les voitures ne bougent pas.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a un arrêt parce que les voitures ne bougent pas.'::text),
(319976,35553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burada bir duruş ..., çünkü arabalar hareket etmiyor.'::text,'var'::text,'var'::text,'olmak'::text,'Burada bir duruş var, çünkü arabalar hareket etmiyor.'::text),
(319977,35553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Itt megállás ..., mert az autók nem mozognak.'::text,'van'::text,'vannak'::text,'lenni'::text,'Itt megállás van, mert az autók nem mozognak.'::text),
(322572,35842,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jedem Helfer im schlimmsten Regen des Jahres!'::text,'dankt'::text,'danken'::text,'dankend'::text,'Sie dankt jedem Helfer im schlimmsten Regen des Jahres!'::text),
(322576,35842,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... кожному помічникові під найгіршим дощем року!'::text,'дякує'::text,'дякувати'::text,'дякуючи'::text,'Вона дякує кожному помічникові під найгіршим дощем року!'::text),
(322575,35842,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... a cada ayudante bajo la peor lluvia del año!'::text,'da las gracias'::text,'dar las gracias'::text,'dando las gracias'::text,'¡Ella da las gracias a cada ayudante bajo la peor lluvia del año!'::text),
(322574,35842,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... chaque personne qui l''aide sous la pire pluie de l''année !'::text,'remercie'::text,'remercier'::text,'remerciant'::text,'Elle remercie chaque personne qui l''aide sous la pire pluie de l''année !'::text),
(322577,35842,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yılın en kötü yağmurunda her yardımcısına ...!'::text,'teşekkür eder'::text,'teşekkür etmek'::text,'teşekkür ederek'::text,'Yılın en kötü yağmurunda her yardımcısına teşekkür eder!'::text),
(322578,35842,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az év legrosszabb esőjében ... minden segítőjének!'::text,'köszönetet mond'::text,'köszönetet mondani'::text,'köszönetet mondó'::text,'Az év legrosszabb esőjében köszönetet mond minden segítőjének!'::text),
(322581,35843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... dem Mann für den Regenschirm danken.'::text,'kann'::text,'kann'::text,'ist'::text,'Sie kann dem Mann für den Regenschirm danken.'::text),
(322585,35843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... подякувати чоловікові за парасольку.'::text,'може'::text,'може'::text,'є'::text,'Вона може подякувати чоловікові за парасольку.'::text),
(322584,35843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... darle las gracias al hombre por el paraguas.'::text,'puede'::text,'puede'::text,'está'::text,'Ella puede darle las gracias al hombre por el paraguas.'::text),
(322583,35843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... remercier l''homme pour le parapluie.'::text,'peut'::text,'peut'::text,'est'::text,'Elle peut remercier l''homme pour le parapluie.'::text),
(322586,35843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şemsiye için adama ...'::text,'teşekkür edebilir'::text,'teşekkür edebilir'::text,NULL::text,'Şemsiye için adama teşekkür edebilir.'::text),
(322587,35843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meg ... köszönni a férfinak az esernyőt.'::text,'tudja'::text,'tudja'::text,'van'::text,'Meg tudja köszönni a férfinak az esernyőt.'::text),
(322599,35845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör dir das an: Sie ... ihm angeblich zweimal, bevor der Bus abfuhr.'::text,'dankte'::text,'dankt'::text,'danken'::text,'Hör dir das an: Sie dankte ihm angeblich zweimal, bevor der Bus abfuhr.'::text),
(322603,35845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай: вона ... йому двічі, поки автобус не поїхав, кажуть.'::text,'подякувала'::text,'дякує'::text,'дякувати'::text,'Слухай: вона подякувала йому двічі, поки автобус не поїхав, кажуть.'::text),
(322602,35845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha esto: por lo visto le ... las gracias dos veces antes de que se fuera el autobús.'::text,'dio'::text,'da'::text,'dar'::text,'Escucha esto: por lo visto le dio las gracias dos veces antes de que se fuera el autobús.'::text),
(322601,35845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : elle ... deux fois avant que le bus parte, paraît-il.'::text,'l''a remercié'::text,'le remercie'::text,'le remercier'::text,'Écoute ça : elle l''a remercié deux fois avant que le bus parte, paraît-il.'::text),
(322604,35845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak: güya otobüs kalkmadan önce ona iki kez ...'::text,'teşekkür etti'::text,'teşekkür eder'::text,'teşekkür etmek'::text,'Şuna bak: güya otobüs kalkmadan önce ona iki kez teşekkür etti.'::text),
(322605,35845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj: állítólag kétszer ... meg neki, mielőtt elment a busz.'::text,'köszönte'::text,'köszöni'::text,'köszönni'::text,'Figyelj: állítólag kétszer köszönte meg neki, mielőtt elment a busz.'::text),
(322608,35846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie vergisst oft, sich bei Leuten zu bedanken, aber gestern ... sie zwei Männern.'::text,'dankte'::text,'dankt'::text,NULL::text,'Sie vergisst oft, sich bei Leuten zu bedanken, aber gestern dankte sie zwei Männern.'::text),
(322612,35846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона часто забуває дякувати людям, але вчора ... двом чоловікам.'::text,'подякувала'::text,'дякує'::text,NULL::text,'Вона часто забуває дякувати людям, але вчора подякувала двом чоловікам.'::text),
(322611,35846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A menudo se olvida de dar las gracias, pero ayer les ... las gracias a dos hombres.'::text,'dio'::text,'da'::text,NULL::text,'A menudo se olvida de dar las gracias, pero ayer les dio las gracias a dos hombres.'::text),
(322610,35846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle oublie souvent de remercier les gens, mais hier elle ... deux hommes.'::text,'a remercié'::text,'remercie'::text,NULL::text,'Elle oublie souvent de remercier les gens, mais hier elle a remercié deux hommes.'::text),
(322613,35846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlara teşekkür etmeyi sık sık unutur ama dün iki adama ...'::text,'teşekkür etti'::text,'teşekkür eder'::text,NULL::text,'İnsanlara teşekkür etmeyi sık sık unutur ama dün iki adama teşekkür etti.'::text),
(322614,35846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyakran elfelejt köszönetet mondani, de tegnap két férfinak ... köszönetet.'::text,'mondott'::text,'mond'::text,NULL::text,'Gyakran elfelejt köszönetet mondani, de tegnap két férfinak mondott köszönetet.'::text),
(322617,35847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mamas Regel: Sie ... jedem danken, der ihr hilft.'::text,'muss'::text,'muss'::text,'sollte'::text,'Mamas Regel: Sie muss jedem danken, der ihr hilft.'::text),
(322621,35847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мамине правило: вона ... дякувати кожному, хто їй допомагає.'::text,'має'::text,'мусить'::text,'мала б'::text,'Мамине правило: вона має дякувати кожному, хто їй допомагає.'::text),
(322620,35847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Norma de su madre: ... dar las gracias a quien la ayude.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Norma de su madre: tiene que dar las gracias a quien la ayude.'::text),
(322619,35847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La règle de sa mère : elle ... remercier toute personne qui l''aide.'::text,'doit'::text,'doit'::text,'devrait'::text,'La règle de sa mère : elle doit remercier toute personne qui l''aide.'::text),
(322622,35847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annesinin kuralı: ona yardım eden herkese ...'::text,'teşekkür etmek zorunda'::text,'teşekkür etmeli'::text,'teşekkür etmeli'::text,'Annesinin kuralı: ona yardım eden herkese teşekkür etmek zorunda.'::text),
(322623,35847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anyja szabálya: meg ... köszönnie mindenkinek, aki segít neki.'::text,'kell'::text,'kell'::text,'kellene'::text,'Az anyja szabálya: meg kell köszönnie mindenkinek, aki segít neki.'::text),
(322635,35849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Papiere sind ruiniert, ... sie dankt dem Mann trotzdem! Eine Heldin!'::text,'aber'::text,'also'::text,'weil'::text,'Ihre Papiere sind ruiniert, aber sie dankt dem Mann trotzdem! Eine Heldin!'::text),
(322639,35849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її папери зіпсовані, ... вона все одно дякує чоловікові! Героїня!'::text,'але'::text,'тому'::text,'бо'::text,'Її папери зіпсовані, але вона все одно дякує чоловікові! Героїня!'::text),
(322638,35849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sus papeles están destrozados, ... le da las gracias al hombre igualmente! ¡Una heroína!'::text,'pero'::text,'así que'::text,'porque'::text,'¡Sus papeles están destrozados, pero le da las gracias al hombre igualmente! ¡Una heroína!'::text),
(322637,35849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses papiers sont fichus, ... elle remercie quand même l''homme ! Une héroïne !'::text,'mais'::text,'donc'::text,'parce qu'''::text,'Ses papiers sont fichus, mais elle remercie quand même l''homme ! Une héroïne !'::text),
(322640,35849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâğıtları mahvoldu ... yine de adama teşekkür ediyor! Tam bir kahraman!'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kâğıtları mahvoldu ama yine de adama teşekkür ediyor! Tam bir kahraman!'::text),
(322641,35849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tönkrementek a papírjai, ... mégis megköszöni a férfinak! Egy hős!'::text,'de'::text,'ezért'::text,'mert'::text,'Tönkrementek a papírjai, de mégis megköszöni a férfinak! Egy hős!'::text),
(293664,32630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den schicken, weil er schick war.'::text,'kaufte'::text,'kaufte'::text,'kaufen'::text,'Er kaufte den schicken, weil er schick war.'::text),
(293668,32630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... розкішний, бо він був розкішний.'::text,'купив'::text,'купив'::text,'купувати'::text,'Він купив розкішний, бо він був розкішний.'::text),
(293667,32630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el lujoso porque era lujoso.'::text,'Compró'::text,'Compró'::text,'Comprar'::text,'Compró el lujoso porque era lujoso.'::text),
(293666,32630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le luxueux parce qu''il était luxueux.'::text,'a acheté'::text,'a acheté'::text,'acheter'::text,'Il a acheté le luxueux parce qu''il était luxueux.'::text),
(293669,32630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süslü olanı süslü olduğu için ...'::text,'aldı'::text,'aldı'::text,'almak'::text,'Süslü olanı süslü olduğu için aldı.'::text),
(293670,32630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a flancosat, mert flancos volt.'::text,'Megvette'::text,'Megvette'::text,'Megvenni'::text,'Megvette a flancosat, mert flancos volt.'::text),
(293673,32631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... ein schicker Kinderwagen an ihr vorbei. Ihr Leben war ruiniert!'::text,'rollte'::text,'rollt'::text,NULL::text,'Gestern rollte ein schicker Kinderwagen an ihr vorbei. Ihr Leben war ruiniert!'::text),
(293677,32631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора повз неї ... розкішний візок. Її життя було зруйноване!'::text,'прокотився'::text,'котиться'::text,NULL::text,'Учора повз неї прокотився розкішний візок. Її життя було зруйноване!'::text),
(293676,32631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer un cochecito lujoso ... a su lado. ¡Su vida quedó arruinada!'::text,'pasó rodando'::text,'pasa rodando'::text,NULL::text,'Ayer un cochecito lujoso pasó rodando a su lado. ¡Su vida quedó arruinada!'::text),
(293675,32631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, une poussette de luxe ... devant elle. Sa vie était fichue !'::text,'est passée'::text,'passe'::text,NULL::text,'Hier, une poussette de luxe est passée devant elle. Sa vie était fichue !'::text),
(293678,32631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün yanından süslü bir bebek arabası ...! Hayatı mahvoldu!'::text,'geçti'::text,'geçer'::text,NULL::text,'Dün yanından süslü bir bebek arabası geçti! Hayatı mahvoldu!'::text),
(293679,32631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap egy flancos babakocsi ... el mellette. Tönkrement az élete!'::text,'gurult'::text,'gurul'::text,NULL::text,'Tegnap egy flancos babakocsi gurult el mellette. Tönkrement az élete!'::text),
(293682,32632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jetzt ... ein Mann einen schicken Kinderwagen an ihr vorbei.'::text,'schiebt'::text,'schiebt'::text,'schiebend'::text,'Jetzt schiebt ein Mann einen schicken Kinderwagen an ihr vorbei.'::text),
(293686,32632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз чоловік ... повз неї розкішний візок.'::text,'штовхає'::text,'штовхає'::text,'штовхаючи'::text,'Зараз чоловік штовхає повз неї розкішний візок.'::text),
(293685,32632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora un hombre ... un cochecito lujoso por delante de ella.'::text,'está empujando'::text,'está empujando'::text,'empujando'::text,'Ahora un hombre está empujando un cochecito lujoso por delante de ella.'::text),
(293684,32632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maintenant, un homme ... une poussette de luxe devant elle.'::text,'est en train de pousser'::text,'est en train de pousser'::text,'poussant'::text,'Maintenant, un homme est en train de pousser une poussette de luxe devant elle.'::text),
(293687,32632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi bir adam yanından süslü bir bebek arabası ...'::text,'itiyor'::text,'itiyor'::text,'iterek'::text,'Şimdi bir adam yanından süslü bir bebek arabası itiyor.'::text),
(293688,32632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most egy férfi egy flancos babakocsit ... el mellette.'::text,'tol'::text,'tol'::text,'toló'::text,'Most egy férfi egy flancos babakocsit tol el mellette.'::text),
(293700,32634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich ... der Hund nach dieser schicken Fahrt einen schlichten Kinderwagen wollen.'::text,'wird'::text,'wird'::text,'will'::text,'Natürlich wird der Hund nach dieser schicken Fahrt einen schlichten Kinderwagen wollen.'::text),
(293704,32634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, пес після цієї розкішної поїздки ... простий візок.'::text,'захоче'::text,'захоче'::text,'хотіти'::text,'Звісно, пес після цієї розкішної поїздки захоче простий візок.'::text),
(293703,32634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, el perro ... un cochecito sencillo después de este paseo de lujo.'::text,'querrá'::text,'querrá'::text,'querer'::text,'Obviamente, el perro querrá un cochecito sencillo después de este paseo de lujo.'::text),
(293702,32634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, le chien ... une poussette toute simple après cette balade de luxe.'::text,'voudra'::text,'voudra'::text,'vouloir'::text,'Évidemment, le chien voudra une poussette toute simple après cette balade de luxe.'::text),
(293705,32634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki köpek bu süslü gezintiden sonra sade bir bebek arabası ...'::text,'isteyecek'::text,'isteyecek'::text,'istemek'::text,'Tabii ki köpek bu süslü gezintiden sonra sade bir bebek arabası isteyecek.'::text),
(293706,32634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván a kutya ezután a flancos kör után egy sima babakocsit ...'::text,'fog akarni'::text,'fog akarni'::text,'akarni'::text,'Nyilván a kutya ezután a flancos kör után egy sima babakocsit fog akarni.'::text),
(293709,32635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sein Kinderwagen ist viel ... als ihrer, echt jetzt.'::text,'schicker'::text,'schicker'::text,'am schicksten'::text,'Alter, sein Kinderwagen ist viel schicker als ihrer, echt jetzt.'::text),
(293713,32635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, його візок набагато ... за її, чесно.'::text,'розкішніший'::text,'більш розкішний'::text,'найрозкішніший'::text,'Бро, його візок набагато розкішніший за її, чесно.'::text),
(293712,32635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, su cochecito es mucho ... que el de ella, en serio.'::text,'más lujoso'::text,'más lujoso'::text,'el más lujoso'::text,'Tío, su cochecito es mucho más lujoso que el de ella, en serio.'::text),
(293711,32635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, sa poussette est carrément ... que la sienne, sérieux.'::text,'plus chic'::text,'plus chic'::text,'la plus chic'::text,'Mec, sa poussette est carrément plus chic que la sienne, sérieux.'::text),
(293714,32635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun bebek arabası kızınkinden çok ..., cidden.'::text,'daha süslü'::text,'daha süslü'::text,'en süslü'::text,'Kanka, onun bebek arabası kızınkinden çok daha süslü, cidden.'::text),
(293715,32635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az ő babakocsija sokkal ..., mint a nőé, komolyan.'::text,'flancosabb'::text,'flancosabb'::text,'legflancosabb'::text,'Tesó, az ő babakocsija sokkal flancosabb, mint a nőé, komolyan.'::text),
(293718,32636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Hund fährt so ... im schicken Kinderwagen, irgendwie ikonisch.'::text,'stolz'::text,'stolz'::text,'Stolz'::text,'Yo, der Hund fährt so stolz im schicken Kinderwagen, irgendwie ikonisch.'::text),
(293722,32636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, цей пес так ... їде в розкішному візку, реально культово.'::text,'гордо'::text,'гордий'::text,'гордість'::text,'Йо, цей пес так гордо їде в розкішному візку, реально культово.'::text),
(293721,32636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ese perro va tan ... en el cochecito de lujo, en plan icónico.'::text,'orgullosamente'::text,'orgulloso'::text,'orgullo'::text,'Oye, ese perro va tan orgullosamente en el cochecito de lujo, en plan icónico.'::text),
(293720,32636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ce chien se balade si ... dans la poussette de luxe, un peu iconique.'::text,'fièrement'::text,'fier'::text,'fierté'::text,'Yo, ce chien se balade si fièrement dans la poussette de luxe, un peu iconique.'::text),
(293723,32636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o köpek süslü bebek arabasında öyle ... gidiyor ki, resmen ikonik.'::text,'gururla'::text,'gururlu'::text,'gurur'::text,'Kanka, o köpek süslü bebek arabasında öyle gururla gidiyor ki, resmen ikonik.'::text),
(293724,32636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, az a kutya olyan ... utazik a flancos babakocsiban, lazán ikonikus.'::text,'büszkén'::text,'büszke'::text,'büszkeség'::text,'Figyu, az a kutya olyan büszkén utazik a flancos babakocsiban, lazán ikonikus.'::text),
(300045,33339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... die beste Nilpferd-Rangerin aller Zeiten sein.'::text,'wirst'::text,'wird'::text,'wirst'::text,'Ehrlich, du wirst die beste Nilpferd-Rangerin aller Zeiten sein.'::text),
(300049,33339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... найкращою рейнджеркою для бегемотів.'::text,'будеш'::text,'буде'::text,'будеш'::text,'Чесно, ти будеш найкращою рейнджеркою для бегемотів.'::text),
(300048,33339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... ser la mejor guardabosques de hipopótamos de la historia.'::text,'vas a'::text,'va a'::text,'vas a'::text,'La verdad, vas a ser la mejor guardabosques de hipopótamos de la historia.'::text),
(300047,33339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... être la meilleure garde d''hippopotames de tous les temps.'::text,'vas'::text,'va'::text,'vas'::text,'Franchement, tu vas être la meilleure garde d''hippopotames de tous les temps.'::text),
(300050,33339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen gelmiş geçmiş en iyi su aygırı korucusu ...'::text,'olacaksın'::text,'olacak'::text,'olacaksın'::text,'Açıkçası sen gelmiş geçmiş en iyi su aygırı korucusu olacaksın.'::text),
(300051,33339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te ... minden idők legjobb vízilórangere.'::text,'leszel'::text,'lesz'::text,'leszel'::text,'Őszintén, te leszel minden idők legjobb vízilórangere.'::text),
(300054,33340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Nilpferd sinkt immer tiefer. Es ...'::text,'wird verschwinden'::text,'wird verschwinden'::text,NULL::text,'Das Nilpferd sinkt immer tiefer. Es wird verschwinden.'::text),
(300058,33340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бегемот занурюється все нижче й нижче. Він ...'::text,'збирається зникнути'::text,'зникне'::text,NULL::text,'Бегемот занурюється все нижче й нижче. Він збирається зникнути.'::text),
(300057,33340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hipopótamo se hunde cada vez más. ...'::text,'Va a desaparecer'::text,'Desaparecerá'::text,NULL::text,'El hipopótamo se hunde cada vez más. Va a desaparecer.'::text),
(300056,33340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hippopotame s''enfonce de plus en plus. Il ...'::text,'va disparaître'::text,'disparaîtra'::text,NULL::text,'L''hippopotame s''enfonce de plus en plus. Il va disparaître.'::text),
(300059,33340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su aygırı gittikçe daha derine batıyor. ...'::text,'Kaybolacak'::text,'Kaybolacak'::text,NULL::text,'Su aygırı gittikçe daha derine batıyor. Kaybolacak.'::text),
(300060,33340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A víziló egyre mélyebbre süllyed. ...'::text,'El fog tűnni'::text,'El fog tűnni'::text,NULL::text,'A víziló egyre mélyebbre süllyed. El fog tűnni.'::text),
(300063,33341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Nilpferd versinkt im grünen ...'::text,'Wasser.'::text,'Wasser.'::text,'ein Wasser.'::text,'Das Nilpferd versinkt im grünen Wasser.'::text),
(300067,33341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бегемот занурюється в зелену ...'::text,'воду.'::text,'воду.'::text,'воду.'::text,'Бегемот занурюється в зелену воду.'::text),
(300066,33341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hipopótamo se hunde en el ... verde.'::text,'agua'::text,'agua'::text,'un agua'::text,'El hipopótamo se hunde en el agua verde.'::text),
(300065,33341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hippopotame s''enfonce dans l''... verte.'::text,'eau'::text,'eau'::text,'une eau'::text,'L''hippopotame s''enfonce dans l''eau verte.'::text),
(300068,33341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su aygırı batıyor, yeşil ...'::text,'suya.'::text,'sulara.'::text,'bir suya.'::text,'Su aygırı batıyor, yeşil suya.'::text),
(300069,33341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A víziló elmerül a zöld ...'::text,'vízben.'::text,'vízben.'::text,'egy vízben.'::text,'A víziló elmerül a zöld vízben.'::text),
(300072,33342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, so nah an einem Steg gibt''s nicht ... Nilpferde.'::text,'viele'::text,'viel'::text,'einige'::text,'Alter, so nah an einem Steg gibt''s nicht viele Nilpferde.'::text),
(300076,33342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, так близько до пристані не буває ... бегемотів.'::text,'багато'::text,'багато'::text,'кількох'::text,'Бро, так близько до пристані не буває багато бегемотів.'::text),
(300075,33342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, no hay ... hipopótamos tan cerca de un embarcadero.'::text,'muchos'::text,'mucho'::text,'algunos'::text,'Tío, no hay muchos hipopótamos tan cerca de un embarcadero.'::text),
(300074,33342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, y a pas ... hippopotames aussi près d''un ponton.'::text,'beaucoup d'''::text,'beaucoup d'''::text,'des'::text,'Mec, y a pas beaucoup d'' hippopotames aussi près d''un ponton.'::text),
(300077,33342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir iskeleye bu kadar yakın ... su aygırı yok.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Kanka, bir iskeleye bu kadar yakın çok su aygırı yok.'::text),
(300078,33342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nincs ... víziló ilyen közel egy stéghez.'::text,'sok'::text,'sok'::text,'néhány'::text,'Tesó, nincs sok víziló ilyen közel egy stéghez.'::text),
(300081,33343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Status-Update: Unter dem Steg ... 1 Nilpferd.'::text,'ist'::text,'sind'::text,'sein'::text,'Status-Update: Unter dem Steg ist 1 Nilpferd.'::text),
(300085,33343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оновлення статусу: під пристанню ... 1 бегемот.'::text,'є'::text,'є'::text,'бути'::text,'Оновлення статусу: під пристанню є 1 бегемот.'::text),
(300084,33343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualización de estado: ... 1 hipopótamo bajo el embarcadero.'::text,'hay'::text,'hay'::text,'hay'::text,'Actualización de estado: hay 1 hipopótamo bajo el embarcadero.'::text),
(300083,33343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Point d''étape : ... 1 hippopotame sous le ponton.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Point d''étape : il y a 1 hippopotame sous le ponton.'::text),
(300086,33343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Durum güncellemesi: iskelenin altında 1 su aygırı ...'::text,'var'::text,'var'::text,'olmak'::text,'Durum güncellemesi: iskelenin altında 1 su aygırı var.'::text),
(300087,33343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Státuszfrissítés: a stég alatt 1 víziló ...'::text,'van'::text,'vannak'::text,'lenni'::text,'Státuszfrissítés: a stég alatt 1 víziló van.'::text),
(300099,33345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... eine Nilpferd-Show moderieren, ganz ehrlich.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Du solltest eine Nilpferd-Show moderieren, ganz ehrlich.'::text),
(300103,33345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... вести шоу про бегемотів, чесно.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Ти мала б вести шоу про бегемотів, чесно.'::text),
(300102,33345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... presentar un programa de hipopótamos, no te voy a mentir.'::text,'Deberías'::text,'Deberías'::text,'Deberías'::text,'Deberías presentar un programa de hipopótamos, no te voy a mentir.'::text),
(300101,33345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... animer un show d''hippopotames, sans mentir.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Tu devrais animer un show d''hippopotames, sans mentir.'::text),
(300104,33345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir su aygırı şovu ..., yalan yok.'::text,'sunmalısın'::text,'sunmalısın'::text,'sunmalısın'::text,'Bir su aygırı şovu sunmalısın, yalan yok.'::text),
(300105,33345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy vízilóshow-t ... vezetned, nem kamu.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Egy vízilóshow-t kellene vezetned, nem kamu.'::text),
(300108,33346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Nilpferd kam nah heran, ... du bist nicht weggerannt. Respekt.'::text,'aber'::text,'also'::text,'weil'::text,'Das Nilpferd kam nah heran, aber du bist nicht weggerannt. Respekt.'::text),
(300112,33346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бегемот підплив близько, ... ти не втекла. Респект.'::text,'але'::text,'тому'::text,'бо'::text,'Бегемот підплив близько, але ти не втекла. Респект.'::text),
(300111,33346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hipopótamo se acercó, ... no saliste corriendo. Respeto.'::text,'pero'::text,'así que'::text,'porque'::text,'El hipopótamo se acercó, pero no saliste corriendo. Respeto.'::text),
(300110,33346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hippopotame s''est approché, ... tu n''as pas couru. Respect.'::text,'mais'::text,'donc'::text,'parce que'::text,'L''hippopotame s''est approché, mais tu n''as pas couru. Respect.'::text),
(300113,33346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su aygırı yaklaştı ... sen kaçmadın. Saygılar.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Su aygırı yaklaştı ama sen kaçmadın. Saygılar.'::text),
(300114,33346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A víziló közel jött, ... nem futottál el. Respekt.'::text,'de'::text,'ezért'::text,'mert'::text,'A víziló közel jött, de nem futottál el. Respekt.'::text),
(316677,35187,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... gerade die albernste Sonnenbrille so selbstbewusst.'::text,'trägst'::text,'trägst'::text,'trägt'::text,'Ehrlich gesagt, du trägst gerade die albernste Sonnenbrille so selbstbewusst.'::text),
(316681,35187,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брешу, ти зараз так упевнено ... найбезглуздіші окуляри.'::text,'носиш'::text,'носиш'::text,'носить'::text,'Не брешу, ти зараз так упевнено носиш найбезглуздіші окуляри.'::text),
(316680,35187,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ahora mismo ... las gafas de sol más ridículas con total seguridad.'::text,'estás llevando'::text,'llevas'::text,'está llevando'::text,'No te voy a mentir, ahora mismo estás llevando las gafas de sol más ridículas con total seguridad.'::text),
(316679,35187,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, là tu ... les lunettes de soleil les plus ridicules avec une telle assurance.'::text,'portes'::text,'portes'::text,'porte'::text,'Sans mentir, là tu portes les lunettes de soleil les plus ridicules avec une telle assurance.'::text),
(316682,35187,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, şu an en saçma güneş gözlüklerini öyle özgüvenle ...'::text,'takıyorsun'::text,'takarsın'::text,'takıyor'::text,'Yalan yok, şu an en saçma güneş gözlüklerini öyle özgüvenle takıyorsun.'::text),
(316683,35187,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, most olyan magabiztosan ... a legbugyutább napszemüveget.'::text,'hordod'::text,'hordod'::text,'hordja'::text,'Nem kamu, most olyan magabiztosan hordod a legbugyutább napszemüveget.'::text),
(316686,35188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du trägst sonst coole Pilotenbrillen, aber heute ... du alberne Herzbrillen. Ikonisch.'::text,'trägst'::text,'trägst'::text,NULL::text,'Du trägst sonst coole Pilotenbrillen, aber heute trägst du alberne Herzbrillen. Ikonisch.'::text),
(316690,35188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зазвичай носиш круті авіатори, але сьогодні ... безглузді окуляри-сердечка. Культово.'::text,'носиш'::text,'носиш'::text,NULL::text,'Ти зазвичай носиш круті авіатори, але сьогодні носиш безглузді окуляри-сердечка. Культово.'::text),
(316689,35188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente llevas unas gafas de aviador guais, pero hoy ... unas gafas de corazón ridículas. Icónico.'::text,'estás llevando'::text,'llevas'::text,NULL::text,'Normalmente llevas unas gafas de aviador guais, pero hoy estás llevando unas gafas de corazón ridículas. Icónico.'::text),
(316688,35188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu portes des lunettes d''aviateur cool, mais aujourd''hui tu ... des lunettes cœur ridicules. Iconique.'::text,'portes'::text,'portes'::text,NULL::text,'D''habitude tu portes des lunettes d''aviateur cool, mais aujourd''hui tu portes des lunettes cœur ridicules. Iconique.'::text),
(316691,35188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde havalı pilot gözlükleri takarsın ama bugün saçma kalpli gözlükler ..., resmen ikonik.'::text,'takıyorsun'::text,'takarsın'::text,NULL::text,'Genelde havalı pilot gözlükleri takarsın ama bugün saçma kalpli gözlükler takıyorsun, resmen ikonik.'::text),
(316692,35188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában menő pilótaszemüveget hordasz, de ma ... egy bugyuta szívecskés szemüveget. Ikonikus.'::text,'hordasz'::text,'hordasz'::text,NULL::text,'Általában menő pilótaszemüveget hordasz, de ma hordasz egy bugyuta szívecskés szemüveget. Ikonikus.'::text),
(316695,35189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr seriöser Look, klar. Alle ... sich an diese albernen Brillen erinnern.'::text,'werden'::text,'werden'::text,'werden'::text,'Sehr seriöser Look, klar. Alle werden sich an diese albernen Brillen erinnern.'::text),
(316699,35189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже серйозний образ, звісно. Усі ... пам''ятати ці безглузді окуляри.'::text,'будуть'::text,'будуть'::text,'будуть'::text,'Дуже серйозний образ, звісно. Усі будуть пам''ятати ці безглузді окуляри.'::text),
(316698,35189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un look muy serio, claro. Todo el mundo ... recordar estas gafas ridículas.'::text,''::text,NULL::text,NULL::text,'Un look muy serio, claro. Todo el mundo recordar estas gafas ridículas.'::text),
(316697,35189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Look très sérieux, évidemment. Tout le monde ... se souvenir de ces lunettes ridicules.'::text,''::text,NULL::text,NULL::text,'Look très sérieux, évidemment. Tout le monde se souvenir de ces lunettes ridicules.'::text),
(316700,35189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok ciddi bir görünüm, tabii ki. Herkes bu saçma gözlükleri ...'::text,'hatırlayacak'::text,'hatırlayacak'::text,'hatırlayacak'::text,'Çok ciddi bir görünüm, tabii ki. Herkes bu saçma gözlükleri hatırlayacak.'::text),
(316701,35189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon komoly szett, persze. Mindenki emlékezni ... ezekre a bugyuta szemüvegekre.'::text,'fog'::text,'fog'::text,'fog'::text,'Nagyon komoly szett, persze. Mindenki emlékezni fog ezekre a bugyuta szemüvegekre.'::text),
(316704,35190,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Modeexperte, klar: Er ... die alberne rote Brille kaufen.'::text,'wird'::text,'werden'::text,'wird'::text,'Ein echter Modeexperte, klar: Er wird die alberne rote Brille kaufen.'::text),
(316708,35190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній модний експерт, звісно: він ... купити ці безглузді червоні окуляри.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Справжній модний експерт, звісно: він збирається купити ці безглузді червоні окуляри.'::text),
(316707,35190,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un experto en moda, claro: ... comprar las gafas rojas ridículas.'::text,'va a'::text,'van a'::text,'va a'::text,'Todo un experto en moda, claro: va a comprar las gafas rojas ridículas.'::text),
(316706,35190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai expert en mode, évidemment : il ... acheter les lunettes rouges ridicules.'::text,'va'::text,'vont'::text,'va'::text,'Un vrai expert en mode, évidemment : il va acheter les lunettes rouges ridicules.'::text),
(316709,35190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir moda uzmanı, tabii ki: saçma kırmızı gözlükleri ...'::text,'alacak'::text,'alacaklar'::text,'alacak'::text,'Gerçek bir moda uzmanı, tabii ki: saçma kırmızı gözlükleri alacak.'::text),
(316710,35190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi divatszakértő, persze: meg ... venni a bugyuta piros szemüveget.'::text,'fogja'::text,'fogják'::text,'fogja'::text,'Igazi divatszakértő, persze: meg fogja venni a bugyuta piros szemüveget.'::text),
(316722,35192,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Herzbrille ist ... als die runde Brille.'::text,'alberner'::text,'alberner'::text,'am albernsten'::text,'Die Herzbrille ist alberner als die runde Brille.'::text),
(316726,35192,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окуляри-сердечка ... за круглі окуляри.'::text,'безглуздіші'::text,'безглуздіші'::text,'найбезглуздіші'::text,'Окуляри-сердечка безглуздіші за круглі окуляри.'::text),
(316725,35192,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las gafas de corazón son ... que las gafas redondas.'::text,'más ridículas'::text,'más ridículas'::text,'las más ridículas'::text,'Las gafas de corazón son más ridículas que las gafas redondas.'::text),
(316724,35192,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les lunettes cœur sont ... que les lunettes rondes.'::text,'plus ridicules'::text,'plus ridicules'::text,'les plus ridicules'::text,'Les lunettes cœur sont plus ridicules que les lunettes rondes.'::text),
(316727,35192,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalpli gözlük yuvarlak gözlükten ...'::text,'daha saçma'::text,'daha saçma'::text,'en saçma'::text,'Kalpli gözlük yuvarlak gözlükten daha saçma.'::text),
(316728,35192,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szívecskés szemüveg ..., mint a kerek szemüveg.'::text,'bugyutább'::text,'bugyutább'::text,'legbugyutább'::text,'A szívecskés szemüveg bugyutább, mint a kerek szemüveg.'::text),
(316731,35193,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er posiert ... mit seiner albernen Brille.'::text,'stolz'::text,'stolz'::text,'Stolz'::text,'Er posiert stolz mit seiner albernen Brille.'::text),
(316735,35193,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... позує у своїх безглуздих окулярах.'::text,'гордо'::text,'гордий'::text,'гордість'::text,'Він гордо позує у своїх безглуздих окулярах.'::text),
(316734,35193,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Posa ... con sus gafas ridículas.'::text,'orgullosamente'::text,'orgulloso'::text,'orgullo'::text,'Posa orgullosamente con sus gafas ridículas.'::text),
(316733,35193,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pose ... avec ses lunettes ridicules.'::text,'fièrement'::text,'fier'::text,'fierté'::text,'Il pose fièrement avec ses lunettes ridicules.'::text),
(316736,35193,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saçma gözlükleriyle ... poz veriyor.'::text,'gururla'::text,'gururlu'::text,'gurur'::text,'Saçma gözlükleriyle gururla poz veriyor.'::text),
(316737,35193,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pózol a bugyuta szemüvegében.'::text,'Büszkén'::text,'Büszke'::text,'Büszkeség'::text,'Büszkén pózol a bugyuta szemüvegében.'::text),
(315201,35023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Becher auf den kleinen Tisch stellen.'::text,'kann'::text,'kann'::text,'ist'::text,'Er kann den Becher auf den kleinen Tisch stellen.'::text),
(315205,35023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... поставити кухоль на маленький столик.'::text,'може'::text,'може'::text,'є'::text,'Він може поставити кухоль на маленький столик.'::text),
(315204,35023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... poner la taza en la mesita.'::text,'puede'::text,'puede'::text,'está'::text,'Él puede poner la taza en la mesita.'::text),
(315203,35023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... poser le mug sur la petite table.'::text,'peut'::text,'peut'::text,'est'::text,'Il peut poser le mug sur la petite table.'::text),
(315206,35023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kupayı küçük masaya ...'::text,'koyabilir'::text,'koyabilir'::text,NULL::text,'Kupayı küçük masaya koyabilir.'::text),
(315207,35023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le ... tenni a bögrét a kis asztalra.'::text,'tudja'::text,'tudja'::text,'van'::text,'Le tudja tenni a bögrét a kis asztalra.'::text),
(315210,35024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... stellt sie die Gläser hin? Rund um den Küchentisch.'::text,'Wohin'::text,'Wann'::text,'Wer'::text,'Wohin stellt sie die Gläser hin? Rund um den Küchentisch.'::text),
